using Microsoft::WRL::ComPtr;

static bool aexrt_env_flag(const char* name) {
    if (!name || !name[0]) return false;
    DWORD required = GetEnvironmentVariableA(name, nullptr, 0);
    if (required == 0) return false;
    std::string value(required, '\0');
    DWORD written = GetEnvironmentVariableA(name, value.data(), required);
    if (written == 0) return true;
    value.resize(written);
    auto first = std::find_if_not(value.begin(), value.end(), [](unsigned char c) { return std::isspace(c) != 0; });
    auto last = std::find_if_not(value.rbegin(), value.rend(), [](unsigned char c) { return std::isspace(c) != 0; }).base();
    if (first >= last) return true;
    std::string normalized(first, last);
    std::transform(normalized.begin(), normalized.end(), normalized.begin(), [](unsigned char c) {
        return static_cast<char>(std::tolower(c));
    });
    return normalized != "0" && normalized != "false" && normalized != "off" && normalized != "no";
}

static uint32_t aexrt_env_u32(const char* name, uint32_t fallback = 0) {
    if (!name || !name[0]) return fallback;
    char value[32]{};
    DWORD written = GetEnvironmentVariableA(name, value, static_cast<DWORD>(sizeof(value)));
    if (written == 0 || written >= sizeof(value)) return fallback;
    char* end = nullptr;
    const unsigned long parsed = std::strtoul(value, &end, 10);
    if (end == value || *end != '\0' || parsed > UINT32_MAX) return fallback;
    return static_cast<uint32_t>(parsed);
}

