struct AexrtBuffer {
    AexrtDevice* owner = nullptr;
    ComPtr<ID3D12Resource> resource;
    uint64_t nbytes = 0;
    uint64_t element_offset = 0;
    uint32_t element_nbytes = sizeof(float);
    D3D12_RESOURCE_STATES state = D3D12_RESOURCE_STATE_COMMON;
};

struct AexrtDescriptorArena {
    ComPtr<ID3D12DescriptorHeap> heap;
    UINT descriptor_size = 0;
    UINT capacity = 0;
    UINT used = 0;
};

struct AexrtUploadRingSlot {
    ComPtr<ID3D12Resource> upload;
    void* mapped = nullptr;
    ComPtr<ID3D12DescriptorHeap> descriptor_heap;
    ComPtr<ID3D12CommandAllocator> command_allocator;
    ComPtr<ID3D12GraphicsCommandList> command_list;
};

struct AexrtPreparedDispatch {
    AexrtDevice* owner = nullptr;
    AexrtBuffer* input = nullptr;
    AexrtBuffer* weight = nullptr;
    AexrtBuffer* bias = nullptr;
    AexrtBuffer* output = nullptr;
    ComPtr<ID3D12DescriptorHeap> descriptor_heap;
    ComPtr<ID3D12CommandAllocator> command_allocator;
    ComPtr<ID3D12GraphicsCommandList> command_list;
    uint64_t element_count = 0;
    AexrtConv2DDesc conv_desc{};
    std::vector<AexrtUploadRingSlot> upload_slots;
    uint32_t next_upload_slot = 0;
    uint64_t input_nbytes = 0;
    bool owns_input = false;

    ~AexrtPreparedDispatch() {
        D3D12_RANGE empty{0, 0};
        for (auto& slot : upload_slots) {
            if (slot.mapped && slot.upload) {
                slot.upload->Unmap(0, &empty);
                slot.mapped = nullptr;
            }
        }
        if (owns_input) {
            aexrt_d3d12_destroy_buffer(input);
            input = nullptr;
        }
    }
};

struct AexrtCompiledGraph {
    AexrtDevice* owner = nullptr;
    AexrtGraphDesc desc{};
    std::vector<AexrtNodeDesc> nodes;
    std::vector<AexrtScalarConstantDesc> constants;
    std::vector<AexrtBuffer*> inputs;
    std::vector<AexrtBuffer*> values;
    std::vector<uint8_t> constant_mask;
    std::vector<float> constant_values;
    std::vector<ComPtr<ID3D12DescriptorHeap>> descriptor_heaps;
    ComPtr<ID3D12CommandAllocator> command_allocator;
    ComPtr<ID3D12GraphicsCommandList> command_list;
    ComPtr<ID3D12RootSignature> fused_root_signature;
    ComPtr<ID3D12PipelineState> fused_pso;
    uint32_t dispatch_count = 0;
    uint32_t allocated_buffer_count = 0;
    uint32_t fusion_kind = 0;
};

struct AexrtReplayValue {
    uint64_t elements = 0;
    std::vector<uint32_t> shape4;
    std::vector<float> cpu;
    std::vector<uint16_t> cpu_fp16;
    std::vector<float> stride2_direct_pack4_weight_cpu;
    std::vector<uint16_t> stride2_direct_pack4_weight_cpu_fp16;
    std::vector<uint16_t> conv3x3_k_major_oc4_weight_cpu_fp16;
    std::vector<float> conv3x3_k_major_oc4_weight_cpu_fp32;
    std::vector<float> winograd_f2x2_weight_cpu;
    std::vector<uint16_t> winograd_f2x2_weight_cpu_fp16;
    std::vector<uint16_t> conv1x1_oc8_weight_cpu_fp16;
    /* Winograd F(4x4)：36 个 fp16 变换点 / (oc,ic)，9 个 uint2 打包。 */
    std::vector<uint16_t> winograd_f4x4_weight_cpu_fp16;
    /* INT8 per-channel：oc*ic*kk 个 int8（按 kernel 家族排布）+ oc 个 fp32
     * scale（拼接在 int8 payload 之后，layout 8 记录）。 */
    std::vector<int8_t> conv_int8_weight_cpu;
    std::vector<float> conv_int8_weight_scale_cpu;
    AexrtBuffer* gpu = nullptr;
    AexrtBuffer* stride2_direct_pack4_weight_gpu = nullptr;
    AexrtBuffer* native_fp16_packed_weight_gpu = nullptr;
    AexrtBuffer* conv3x3_k_major_oc4_weight_gpu = nullptr;
    AexrtBuffer* conv3x3_k_major_oc4_weight_fp32_gpu = nullptr;
    AexrtBuffer* winograd_f2x2_weight_gpu = nullptr;
    AexrtBuffer* winograd_f2x2_weight_fp16_gpu = nullptr;
    AexrtBuffer* conv1x1_oc8_weight_fp16_gpu = nullptr;
    AexrtBuffer* winograd_f4x4_weight_fp16_gpu = nullptr;
    AexrtBuffer* conv_int8_weight_gpu = nullptr;
    AexrtBuffer* conv_int8_weight_scale_gpu = nullptr;
    /* 生产者侧预量化激活镜像：每帧由量化 dispatch 重算（amax 组归约 ->
     * 按通道四元组打包 int8）。录制期去重标志：同一输入+变体在同一
     * prepare 内只录一次 quant，多消费者共享。 */
    AexrtBuffer* int8_activation_gpu = nullptr;
    AexrtBuffer* int8_activation_amax_gpu = nullptr;
    uint64_t int8_activation_elements = 0;
    uint32_t int8_quant_recorded_variants = 0;  /* bit0=per-tensor, bit1=pg16 */
    /* Producer-amax: the producing conv's epilogue atomic-maxes this value's
     * amax slots, so its quant chain needs only the pack (which also clears
     * the slots for the next frame). */
    bool int8_amax_from_producer = false;
    /* Wave-Slice K-split partial scratch buffer. */
    AexrtBuffer* ks_partial_gpu = nullptr;
    uint64_t ks_partial_elements = 0;
    uint64_t stride2_direct_pack4_weight_elements = 0;
    uint32_t stride2_direct_pack4_weight_in_channels = 0;
    uint32_t stride2_direct_pack4_weight_out_channels = 0;
    uint64_t native_fp16_packed_weight_elements = 0;
    uint32_t native_fp16_packed_weight_in_channels = 0;
    uint32_t native_fp16_packed_weight_out_channels = 0;
    uint64_t conv3x3_k_major_oc4_weight_elements = 0;
    uint32_t conv3x3_k_major_oc4_weight_in_channels = 0;
    uint32_t conv3x3_k_major_oc4_weight_out_channels = 0;
    uint64_t winograd_f2x2_weight_elements = 0;
    uint32_t winograd_f2x2_weight_in_channels = 0;
    uint32_t winograd_f2x2_weight_out_channels = 0;
    uint64_t winograd_f2x2_weight_fp16_elements = 0;
    uint32_t winograd_f2x2_weight_fp16_in_channels = 0;
    uint32_t winograd_f2x2_weight_fp16_out_channels = 0;
    uint64_t conv1x1_oc8_weight_fp16_elements = 0;
    uint32_t conv1x1_oc8_weight_fp16_in_channels = 0;
    uint32_t conv1x1_oc8_weight_fp16_out_channels = 0;
    uint64_t winograd_f4x4_weight_fp16_elements = 0;
    uint32_t winograd_f4x4_weight_fp16_in_channels = 0;
    uint32_t winograd_f4x4_weight_fp16_out_channels = 0;
    uint64_t conv_int8_weight_elements = 0;
    uint32_t conv_int8_weight_in_channels = 0;
    uint32_t conv_int8_weight_out_channels = 0;
    uint32_t conv_int8_weight_kernel_elems = 0;
    uint64_t engine_arena_offset_bytes = UINT64_MAX;
    uint64_t engine_arena_nbytes = 0;
    uint32_t engine_arena_page = 0;
    uint32_t engine_storage_dtype = 1;
    uint32_t engine_storage_layout = 1;
    bool owns_gpu = false;
    bool is_input = false;
    bool is_constant = false;
};

