static bool should_use_conv3x3_stride2_direct_pack4_silu(const AexrtConv2DDesc& desc) {
    if (aexrt_env_flag("AEXRT_NATIVE_D3D12_DISABLE_STRIDE2_DIRECT_PACK4_3X3")) return false;
    if (!is_conv3x3_stride2_tiled_fast_path(desc)) return false;
    if (!aexrt_env_flag("AEXRT_NATIVE_D3D12_DISABLE_FIRSTCONV_STRIDE2_DIRECT_PACK4_3X3") &&
        desc.in_channels == 3 &&
        desc.out_channels >= 16 &&
        (desc.out_channels % 4u) == 0 &&
        desc.out_h == 160 &&
        desc.out_w == 160) return true;
    if (desc.in_channels < 32 || desc.out_channels < 64) return false;
    return uint64_t(desc.out_h) * desc.out_w >= 100;
}

static bool should_use_conv3x3_stride2_direct_pack4_packed_weight_silu(const AexrtConv2DDesc& desc) {
    if (aexrt_env_flag("AEXRT_NATIVE_D3D12_DISABLE_STRIDE2_DIRECT_PACK4_PACKED_WEIGHT_3X3")) return false;
    if (!is_conv3x3_stride2_tiled_fast_path(desc)) return false;
    if ((desc.out_channels % 4) != 0) return false;

    if (desc.out_h == 40 && desc.out_w == 40 && desc.in_channels == 128 && desc.out_channels == 128) return true;
    if (desc.out_h == 20 && desc.out_w == 20 && desc.in_channels == 256 && desc.out_channels == 256) return true;

    if (!aexrt_env_flag("AEXRT_NATIVE_D3D12_ENABLE_EXPERIMENTAL_STRIDE2_DIRECT_PACK4_PACKED_WEIGHT_3X3") &&
        !aexrt_env_flag("AEXRT_NATIVE_D3D12_FORCE_STRIDE2_DIRECT_PACK4_PACKED_WEIGHT_3X3")) return false;
    if (desc.out_h == 40 && desc.out_w == 40 && desc.in_channels == 128 && desc.out_channels == 128) return true;
    if (desc.out_h == 20 && desc.out_w == 20 && desc.in_channels == 128 && desc.out_channels == 128) return true;
    if (desc.out_h == 20 && desc.out_w == 20 && desc.in_channels == 256 && desc.out_channels == 256) return true;
    if (desc.out_h == 10 && desc.out_w == 10 && desc.in_channels == 256 && desc.out_channels == 256) return true;
    if (desc.out_h == 10 && desc.out_w == 10 && desc.in_channels == 256 && desc.out_channels == 512) return true;
    return false;
}

static bool should_use_conv3x3_stride2_direct_pack4_packed_weight_pos2_silu(const AexrtConv2DDesc& desc) {
    if (aexrt_env_flag("AEXRT_NATIVE_D3D12_DISABLE_STRIDE2_DIRECT_PACK4_PACKED_WEIGHT_POS2_3X3")) return false;
    if (!aexrt_env_flag("AEXRT_NATIVE_D3D12_ENABLE_EXPERIMENTAL_STRIDE2_DIRECT_PACK4_PACKED_WEIGHT_POS2_3X3") &&
        !aexrt_env_flag("AEXRT_NATIVE_D3D12_FORCE_STRIDE2_DIRECT_PACK4_PACKED_WEIGHT_POS2_3X3")) return false;
    return is_conv3x3_stride2_tiled_fast_path(desc) &&
        desc.out_h == 10 &&
        desc.out_w == 10 &&
        desc.in_channels == 256 &&
        desc.out_channels == 512 &&
        (desc.out_channels % 4) == 0;
}

static bool should_use_conv3x3_stride2_direct_pack4_packed_weight_oc8_silu(const AexrtConv2DDesc& desc) {
    if (aexrt_env_flag("AEXRT_NATIVE_D3D12_DISABLE_STRIDE2_DIRECT_PACK4_PACKED_WEIGHT_OC8_3X3")) return false;
    if (is_conv3x3_stride2_tiled_fast_path(desc) &&
        desc.out_h == 40 &&
        desc.out_w == 40 &&
        desc.in_channels == 128 &&
        desc.out_channels == 128) return true;
    if (!aexrt_env_flag("AEXRT_NATIVE_D3D12_ENABLE_EXPERIMENTAL_STRIDE2_DIRECT_PACK4_PACKED_WEIGHT_OC8_3X3") &&
        !aexrt_env_flag("AEXRT_NATIVE_D3D12_FORCE_STRIDE2_DIRECT_PACK4_PACKED_WEIGHT_OC8_3X3")) return false;
    if (!is_conv3x3_stride2_tiled_fast_path(desc) || (desc.out_channels % 8) != 0) return false;
    if (desc.out_h == 40 && desc.out_w == 40 && desc.in_channels == 128 && desc.out_channels == 128) return true;
    if (desc.out_h == 20 && desc.out_w == 20 && desc.in_channels == 256 && desc.out_channels == 256) return true;
    return false;
}

static bool should_use_conv3x3_stride2_direct_pack4_10x10_256x512_interior_silu(const AexrtConv2DDesc& desc) {
    if (aexrt_env_flag("AEXRT_NATIVE_D3D12_DISABLE_STRIDE2_DIRECT_PACK4_10X10_256X512_INTERIOR_3X3")) return false;
    if (!aexrt_env_flag("AEXRT_NATIVE_D3D12_ENABLE_EXPERIMENTAL_STRIDE2_DIRECT_PACK4_10X10_256X512_INTERIOR_3X3") &&
        !aexrt_env_flag("AEXRT_NATIVE_D3D12_FORCE_STRIDE2_DIRECT_PACK4_10X10_256X512_INTERIOR_3X3")) return false;
    if (aexrt_env_flag("AEXRT_NATIVE_D3D12_FORCE_STRIDE2_DIRECT_PACK4_PACKED_WEIGHT_3X3") ||
        aexrt_env_flag("AEXRT_NATIVE_D3D12_FORCE_STRIDE2_DIRECT_PACK4_PACKED_WEIGHT_POS2_3X3") ||
        aexrt_env_flag("AEXRT_NATIVE_D3D12_FORCE_STRIDE2_DIRECT_PACK4_PACKED_WEIGHT_OC8_3X3") ||
        aexrt_env_flag("AEXRT_NATIVE_D3D12_FORCE_STRIDE2_DIRECT_PACK8_3X3") ||
        aexrt_env_flag("AEXRT_NATIVE_D3D12_FORCE_STRIDE2_DIRECT_PACK4_EXACT_3X3")) return false;
    return is_conv3x3_stride2_tiled_fast_path(desc) &&
        desc.out_h == 10 &&
        desc.out_w == 10 &&
        desc.in_channels == 256 &&
        desc.out_channels == 512;
}

