    if (idx >= total) return;

    uint pos = idx % spatial;
    uint t = idx / spatial;
    uint oc_group = t % oc_groups;
    uint n = t / oc_groups;
    uint oh = pos / out_w;
    uint ow = pos - oh * out_w;
