static bool should_use_conv3x3_stride2_persistent_tile16_silu(const AexrtConv2DDesc& desc) {
    if (aexrt_env_flag("AEXRT_NATIVE_D3D12_DISABLE_STRIDE2_PERSISTENT_TILE16_3X3")) return false;
    if (!aexrt_env_flag("AEXRT_NATIVE_D3D12_ENABLE_EXPERIMENTAL_STRIDE2_PERSISTENT_TILE16_3X3") &&
        !aexrt_env_flag("AEXRT_NATIVE_D3D12_FORCE_STRIDE2_PERSISTENT_TILE16_3X3")) return false;
    return is_conv3x3_stride2_tiled_fast_path(desc) &&
        desc.in_channels >= 16 && (desc.in_channels % 16) == 0 &&
        desc.out_channels >= 16 && (desc.out_channels % 16) == 0;
}

