static HRESULT ensure_conv3x3s2_silu_splitk_10x10_256x512_reduce_pipeline(AexrtDevice* ctx) {
    if (!ctx) return E_INVALIDARG;
    if (ctx->conv3x3_splitk_reduce_root_signature && ctx->conv3x3s2_silu_splitk_10x10_256x512_reduce_pso) return S_OK;
    if (!ctx->conv3x3_splitk_reduce_root_signature) {
        HRESULT hr = make_replay_two_table_root(ctx, 2, 1, 16, ctx->conv3x3_splitk_reduce_root_signature.ReleaseAndGetAddressOf());
        if (FAILED(hr)) return hr;
    }
    const char* shader_source = R"(
#define AEXRT_SPLITS 4u
#define AEXRT_OUT_CHANNELS 512u
#define AEXRT_SPATIAL 100u
StructuredBuffer<float> partials : register(t0);
StructuredBuffer<float> bias : register(t1);
RWStructuredBuffer<float> output : register(u0);
cbuffer AexrtConv2DConstants : register(b0) {
    uint batch; uint in_channels; uint in_h; uint in_w;
    uint out_channels; uint out_h; uint out_w;
    uint kernel_h; uint kernel_w; uint stride_h; uint stride_w;
    uint pad_top; uint pad_left; uint dilation_h; uint dilation_w; uint groups;
};

[numthreads(256, 1, 1)]
void main(uint3 tid : SV_DispatchThreadID) {
    uint idx = tid.x;
    uint total = batch * AEXRT_OUT_CHANNELS * AEXRT_SPATIAL;
    if (idx >= total) return;
    uint pos = idx % AEXRT_SPATIAL;
    uint t = idx / AEXRT_SPATIAL;
    uint oc = t % AEXRT_OUT_CHANNELS;
    uint n = t / AEXRT_OUT_CHANNELS;
    float acc = bias[oc];
    [unroll]
    for (uint split = 0u; split < AEXRT_SPLITS; ++split) {
        uint partial_idx = (((n * AEXRT_SPLITS + split) * AEXRT_OUT_CHANNELS + oc) * AEXRT_SPATIAL) + pos;
        acc += partials[partial_idx];
    }
    float sig = 1.0 / (1.0 + exp(-acc));
    output[idx] = acc * sig;
}
)";
    return compile_replay_compute_pso(
        ctx,
        ctx->conv3x3_splitk_reduce_root_signature.Get(),
        shader_source,
        "aexrt_conv3x3s2_silu_splitk_10x10_256x512_reduce_float32",
        ctx->conv3x3s2_silu_splitk_10x10_256x512_reduce_pso.ReleaseAndGetAddressOf());
}

static HRESULT ensure_conv3x3_silu_splitk_20x20_256x64_partial_pipeline(AexrtDevice* ctx) {
    if (!ctx) return E_INVALIDARG;
    if (ctx->conv_root_signature && ctx->conv3x3_silu_splitk_20x20_256x64_partial_pso) return S_OK;
    if (!ctx->conv_root_signature) {
        HRESULT hr = ensure_conv_silu_pipeline(ctx);
        if (FAILED(hr)) return hr;
    }
    const char* shader_source = R"(
#define AEXRT_SPLITS 4u
#define AEXRT_SPLIT_IC 64u
#define AEXRT_IN_CHANNELS 256u
#define AEXRT_OUT_CHANNELS 64u
#define AEXRT_OUT_DIM 20u
#define AEXRT_SPATIAL 400u
#define AEXRT_OC_TILE 8u
StructuredBuffer<float> input : register(t0);
StructuredBuffer<float> weight : register(t1);
StructuredBuffer<float> bias_unused : register(t2);
RWStructuredBuffer<float> partials : register(u0);
cbuffer AexrtConv2DConstants : register(b0) {
    uint batch; uint in_channels; uint in_h; uint in_w;
    uint out_channels; uint out_h; uint out_w;
    uint kernel_h; uint kernel_w; uint stride_h; uint stride_w;
    uint pad_top; uint pad_left; uint dilation_h; uint dilation_w; uint groups;
};

[numthreads(8, 16, 1)]
void main(uint3 group_id : SV_GroupID, uint3 group_tid : SV_GroupThreadID) {
    uint oc = group_id.y * AEXRT_OC_TILE + group_tid.x;
    uint pos = group_id.x * 16u + group_tid.y;
    uint split = group_id.z % AEXRT_SPLITS;
    uint n = group_id.z / AEXRT_SPLITS;
    if (oc >= AEXRT_OUT_CHANNELS || pos >= AEXRT_SPATIAL || n >= batch) return;
    uint oh = pos / AEXRT_OUT_DIM;
    uint ow = pos - oh * AEXRT_OUT_DIM;
    uint ic_begin = split * AEXRT_SPLIT_IC;
    uint ic_end = ic_begin + AEXRT_SPLIT_IC;
    float acc = 0.0;
    [loop]
    for (uint ic = ic_begin; ic < ic_end; ++ic) {
        uint w_base = (oc * AEXRT_IN_CHANNELS + ic) * 9u;
        [unroll]
        for (uint ky = 0u; ky < 3u; ++ky) {
            int ih = int(oh + ky) - 1;
            if (ih < 0 || ih >= int(AEXRT_OUT_DIM)) continue;
            [unroll]
            for (uint kx = 0u; kx < 3u; ++kx) {
                int iw = int(ow + kx) - 1;
                if (iw < 0 || iw >= int(AEXRT_OUT_DIM)) continue;
                uint input_idx = ((n * AEXRT_IN_CHANNELS + ic) * AEXRT_OUT_DIM + uint(ih)) * AEXRT_OUT_DIM + uint(iw);
                acc += input[input_idx] * weight[w_base + ky * 3u + kx];
            }
        }
    }
    uint partial_idx = (((n * AEXRT_SPLITS + split) * AEXRT_OUT_CHANNELS + oc) * AEXRT_SPATIAL) + pos;
    partials[partial_idx] = acc;
}
)";
    ComPtr<ID3DBlob> shader;
    ComPtr<ID3DBlob> errors;
    HRESULT hr = D3DCompile(shader_source, std::strlen(shader_source), "aexrt_conv3x3_silu_splitk_20x20_256x64_partial_float32", nullptr, nullptr, "main", "cs_5_0", D3DCOMPILE_OPTIMIZATION_LEVEL3, 0, &shader, &errors);
    if (FAILED(hr)) return hr;
    D3D12_COMPUTE_PIPELINE_STATE_DESC pso{};
    pso.pRootSignature = ctx->conv_root_signature.Get();
    pso.CS.pShaderBytecode = shader->GetBufferPointer();
    pso.CS.BytecodeLength = shader->GetBufferSize();
    return aexrt_create_compute_pipeline_state(ctx, &pso, IID_PPV_ARGS(ctx->conv3x3_silu_splitk_20x20_256x64_partial_pso.ReleaseAndGetAddressOf()));
}

