static HRESULT ensure_conv3x3s2_silu_implicit_gemm_exact_pipeline(
    AexrtDevice* ctx,
    uint32_t out_dim,
    uint32_t in_channels,
    uint32_t out_channels) {
    if (!ctx) return E_INVALIDARG;
    ComPtr<ID3D12PipelineState>* target = nullptr;
    const char* shader_name = nullptr;
    if (out_dim == 80 && in_channels == 32 && out_channels == 64) {
        target = std::addressof(ctx->conv3x3s2_silu_implicit_gemm_80x80_32x64_pso);
        shader_name = "aexrt_conv3x3s2_silu_implicit_gemm_80x80_32x64_float32";
    } else if (out_dim == 40 && in_channels == 128 && out_channels == 128) {
        target = std::addressof(ctx->conv3x3s2_silu_implicit_gemm_40x40_128x128_pso);
        shader_name = "aexrt_conv3x3s2_silu_implicit_gemm_40x40_128x128_float32";
    } else if (out_dim == 20 && in_channels == 128 && out_channels == 128) {
        target = std::addressof(ctx->conv3x3s2_silu_implicit_gemm_20x20_128x128_pso);
        shader_name = "aexrt_conv3x3s2_silu_implicit_gemm_20x20_128x128_float32";
    } else if (out_dim == 20 && in_channels == 256 && out_channels == 256) {
        target = std::addressof(ctx->conv3x3s2_silu_implicit_gemm_20x20_256x256_pso);
        shader_name = "aexrt_conv3x3s2_silu_implicit_gemm_20x20_256x256_float32";
    } else if (out_dim == 10 && in_channels == 256 && out_channels == 256) {
        target = std::addressof(ctx->conv3x3s2_silu_implicit_gemm_10x10_256x256_pso);
        shader_name = "aexrt_conv3x3s2_silu_implicit_gemm_10x10_256x256_float32";
    } else if (out_dim == 10 && in_channels == 256 && out_channels == 512) {
        target = std::addressof(ctx->conv3x3s2_silu_implicit_gemm_10x10_256x512_pso);
        shader_name = "aexrt_conv3x3s2_silu_implicit_gemm_10x10_256x512_float32";
    } else {
        return E_INVALIDARG;
    }
    if (ctx->conv_root_signature && *target) return S_OK;
    if (!ctx->conv_root_signature) {
        HRESULT hr = ensure_conv_silu_pipeline(ctx);
        if (FAILED(hr)) return hr;
    }

    const uint32_t m_tile = 16u;
    const uint32_t n_tile = out_dim == 10 ? 20u : 16u;
    const uint32_t k_tile = 32u;
    const uint32_t spatial = out_dim * out_dim;
    const uint32_t in_dim = out_dim * 2u;
    const uint32_t k_total = in_channels * 9u;
    std::ostringstream source;
    source
        << "#define AEXRT_M_TILE " << m_tile << "u\n"
        << "#define AEXRT_N_TILE " << n_tile << "u\n"
        << "#define AEXRT_K_TILE " << k_tile << "u\n"
        << "#define AEXRT_OUT_DIM " << out_dim << "u\n"
        << "#define AEXRT_IN_DIM " << in_dim << "u\n"
        << "#define AEXRT_SPATIAL " << spatial << "u\n"
        << "#define AEXRT_IN_CHANNELS " << in_channels << "u\n"
        << "#define AEXRT_OUT_CHANNELS " << out_channels << "u\n"
        << "#define AEXRT_K_TOTAL " << k_total << "u\n"
        << R"(
StructuredBuffer<float> aexrt_input : register(t0);
StructuredBuffer<float> aexrt_weight : register(t1);
StructuredBuffer<float> aexrt_bias : register(t2);
RWStructuredBuffer<float> aexrt_output : register(u0);
cbuffer AexrtConv2DConstants : register(b0) {
    uint batch; uint in_channels; uint in_h; uint in_w;
    uint out_channels; uint out_h; uint out_w;
    uint kernel_h; uint kernel_w; uint stride_h; uint stride_w;
    uint pad_top; uint pad_left; uint dilation_h; uint dilation_w; uint groups;
};
groupshared float w_tile[AEXRT_M_TILE * AEXRT_K_TILE];
groupshared float x_tile[AEXRT_K_TILE * AEXRT_N_TILE];

[numthreads(AEXRT_M_TILE, AEXRT_N_TILE, 1)]
void main(uint3 group_id : SV_GroupID, uint3 group_tid : SV_GroupThreadID) {
    uint local_m = group_tid.x;
    uint local_n = group_tid.y;
    uint linear = local_n * AEXRT_M_TILE + local_m;
    uint oc = group_id.y * AEXRT_M_TILE + local_m;
    uint n_index = group_id.x * AEXRT_N_TILE + local_n;
    uint total_n = batch * AEXRT_SPATIAL;
    uint batch_id = n_index / AEXRT_SPATIAL;
    uint pos = n_index - batch_id * AEXRT_SPATIAL;
    uint oh = pos / AEXRT_OUT_DIM;
    uint ow = pos - oh * AEXRT_OUT_DIM;
    float acc = aexrt_bias[oc];

    [loop]
    for (uint k_base = 0u; k_base < AEXRT_K_TOTAL; k_base += AEXRT_K_TILE) {
        for (uint e = linear; e < AEXRT_M_TILE * AEXRT_K_TILE; e += AEXRT_M_TILE * AEXRT_N_TILE) {
            uint wm = e / AEXRT_K_TILE;
            uint wk = e - wm * AEXRT_K_TILE;
            uint load_oc = group_id.y * AEXRT_M_TILE + wm;
            uint kg = k_base + wk;
            uint ic = kg / 9u;
            uint kk = kg - ic * 9u;
            w_tile[e] = aexrt_weight[(load_oc * AEXRT_IN_CHANNELS + ic) * 9u + kk];
        }
        for (uint xe = linear; xe < AEXRT_K_TILE * AEXRT_N_TILE; xe += AEXRT_M_TILE * AEXRT_N_TILE) {
            uint xk = xe / AEXRT_N_TILE;
            uint xn = xe - xk * AEXRT_N_TILE;
            uint load_n = group_id.x * AEXRT_N_TILE + xn;
            uint kg2 = k_base + xk;
            float xv = 0.0;
            if (load_n < total_n) {
                uint load_batch = load_n / AEXRT_SPATIAL;
                uint load_pos = load_n - load_batch * AEXRT_SPATIAL;
                uint load_oh = load_pos / AEXRT_OUT_DIM;
                uint load_ow = load_pos - load_oh * AEXRT_OUT_DIM;
                uint ic2 = kg2 / 9u;
                uint kk2 = kg2 - ic2 * 9u;
                uint ky = kk2 / 3u;
                uint kx = kk2 - ky * 3u;
                int ih = int(load_oh * 2u + ky) - 1;
                int iw = int(load_ow * 2u + kx) - 1;
                if (ih >= 0 && iw >= 0) {
                    uint input_idx = ((load_batch * AEXRT_IN_CHANNELS + ic2) * AEXRT_IN_DIM + uint(ih)) * AEXRT_IN_DIM + uint(iw);
                    xv = aexrt_input[input_idx];
                }
            }
            x_tile[xe] = xv;
        }
        GroupMemoryBarrierWithGroupSync();
        if (n_index < total_n) {
            [unroll]
            for (uint kk3 = 0u; kk3 < AEXRT_K_TILE; ++kk3) {
                acc += w_tile[local_m * AEXRT_K_TILE + kk3] * x_tile[kk3 * AEXRT_N_TILE + local_n];
            }
        }
        GroupMemoryBarrierWithGroupSync();
    }

    if (n_index < total_n) {
        uint out_idx = ((batch_id * AEXRT_OUT_CHANNELS + oc) * AEXRT_SPATIAL) + pos;
        float sig = 1.0 / (1.0 + exp(-acc));
        aexrt_output[out_idx] = acc * sig;
    }
}
)";
    const std::string shader_source = source.str();
    ComPtr<ID3DBlob> shader;
    ComPtr<ID3DBlob> errors;
    HRESULT hr = D3DCompile(shader_source.c_str(), shader_source.size(), shader_name, nullptr, nullptr, "main", "cs_5_0", D3DCOMPILE_OPTIMIZATION_LEVEL3, 0, &shader, &errors);
    if (FAILED(hr)) return hr;
    D3D12_COMPUTE_PIPELINE_STATE_DESC pso{};
    pso.pRootSignature = ctx->conv_root_signature.Get();
    pso.CS.pShaderBytecode = shader->GetBufferPointer();
    pso.CS.BytecodeLength = shader->GetBufferSize();
    return aexrt_create_compute_pipeline_state(ctx, &pso, IID_PPV_ARGS(target->ReleaseAndGetAddressOf()));
}

