static const char* tileflow_conv_algorithm_name(AexrtTileFlowConvAlgorithm algorithm) {
    switch (algorithm) {
        case AexrtTileFlowConvAlgorithm::Conv1x1: return "conv1x1";
        case AexrtTileFlowConvAlgorithm::Spatial3x3: return "spatial3x3";
        case AexrtTileFlowConvAlgorithm::Spatial3x3Pack4: return "spatial3x3_pack4";
        case AexrtTileFlowConvAlgorithm::Spatial3x3Pack8: return "spatial3x3_pack8";
        case AexrtTileFlowConvAlgorithm::Spatial3x3Stride2Pack4: return "stride2_spatial3x3_pack4";
        case AexrtTileFlowConvAlgorithm::Spatial3x3Stride2DirectPack4: return "stride2_direct_pack4";
        case AexrtTileFlowConvAlgorithm::Spatial3x3Stride2DirectPack4Exact: return "stride2_direct_pack4_exact";
        case AexrtTileFlowConvAlgorithm::Spatial3x3Stride2DirectPack4PackedWeight: return "stride2_direct_pack4_packedw";
        case AexrtTileFlowConvAlgorithm::Spatial3x3Stride2DirectPack4PackedWeightPos2: return "stride2_direct_pack4_packedw_pos2";
        case AexrtTileFlowConvAlgorithm::Spatial3x3Stride2DirectPack4PackedWeightOc8: return "stride2_direct_pack4_packedw_oc8";
        case AexrtTileFlowConvAlgorithm::Spatial3x3Stride2DirectPack4_10x10_256x512Interior: return "stride2_direct_pack4_10x10_256x512_interior";
        case AexrtTileFlowConvAlgorithm::SplitK3x3Stride2_10x10_256x512: return "splitk_stride2_10x10_256x512";
        case AexrtTileFlowConvAlgorithm::TileFlowSpatial3x3_40x40_128x64: return "tileflow_spatial_40x40_128x64";
        case AexrtTileFlowConvAlgorithm::TileFlowSpatial3x3_20x20_256x64: return "tileflow_spatial_20x20_256x64";
        case AexrtTileFlowConvAlgorithm::Spatial3x3DirectPack4PackedWeightPos2: return "direct_pack4_packedw_pos2";
        case AexrtTileFlowConvAlgorithm::WinogradF2x2_3x3: return "winograd_f2x2";
        case AexrtTileFlowConvAlgorithm::Spatial3x3Stride2PersistentTile16: return "stride2_persistent_tile16";
        case AexrtTileFlowConvAlgorithm::Spatial6x6Stride2DirectPack4: return "stride2_direct_pack4_6x6";
        case AexrtTileFlowConvAlgorithm::Spatial3x3Stride2NativeFp16PackedWeight: return "stride2_native_fp16_packedw";
        case AexrtTileFlowConvAlgorithm::Spatial3x3NativeFp16PackedWeightPos2_40x40_64x64: return "native_fp16_packedw_pos2_40x40_64x64";
        case AexrtTileFlowConvAlgorithm::NativeFp16Conv1x1Oc8Pos2: return "native_fp16_conv1x1_oc8_pos2";
        case AexrtTileFlowConvAlgorithm::WinogradF2x2_3x3Fp32Accum: return "winograd_f2x2_fp32_accum";
        case AexrtTileFlowConvAlgorithm::Spatial3x3Stride2NativeFp16PositionPair_40x40_256x256: return "stride2_native_fp16_position_pair_40x40_256x256";
        case AexrtTileFlowConvAlgorithm::Spatial3x3Stride2NativeFp16PositionQuartet_80x80_128x128: return "stride2_native_fp16_position_quartet_80x80_128x128";
        case AexrtTileFlowConvAlgorithm::Spatial3x3Stride2DirectPack4PackedWeightPos4_80x80_128x128: return "stride2_direct_pack4_packedw_pos4_80x80_128x128";
        case AexrtTileFlowConvAlgorithm::Spatial3x3Stride2PositionQuartetKMajorFp32_80x80_128x128: return "stride2_position_quartet_kmajor_fp32_80x80_128x128";
        case AexrtTileFlowConvAlgorithm::Int8Dot4Conv1x1: return "int8_dot4_conv1x1";
        case AexrtTileFlowConvAlgorithm::Int8Dot4Conv3x3: return "int8_dot4_conv3x3";
        case AexrtTileFlowConvAlgorithm::Int8Dot4Conv3x3Stride2: return "int8_dot4_conv3x3_stride2";
        case AexrtTileFlowConvAlgorithm::WinogradF4x4_3x3: return "winograd_f4x4";
        case AexrtTileFlowConvAlgorithm::Spatial3x3Stride2DirectPack8: return "stride2_direct_pack8";
        case AexrtTileFlowConvAlgorithm::Spatial3x3DirectPack4: return "direct_pack4";
        case AexrtTileFlowConvAlgorithm::ImplicitGemm3x3: return "implicit_gemm";
        case AexrtTileFlowConvAlgorithm::ImplicitGemm3x3_40x40: return "implicit_gemm_40x40";
        case AexrtTileFlowConvAlgorithm::ImplicitGemm3x3_20x20: return "implicit_gemm_20x20";
        case AexrtTileFlowConvAlgorithm::ImplicitGemm3x3_10x10: return "implicit_gemm_10x10";
        case AexrtTileFlowConvAlgorithm::ImplicitGemm3x3_40x40_64x64: return "implicit_gemm_40x40_64x64";
        case AexrtTileFlowConvAlgorithm::ImplicitGemm3x3_20x20_64x64: return "implicit_gemm_20x20_64x64";
        case AexrtTileFlowConvAlgorithm::ImplicitGemm3x3_10x10_128x128: return "implicit_gemm_10x10_128x128";
        case AexrtTileFlowConvAlgorithm::ImplicitGemm3x3_20x20_128x64: return "implicit_gemm_20x20_128x64";
        case AexrtTileFlowConvAlgorithm::ImplicitGemm3x3_20x20_256x64: return "implicit_gemm_20x20_256x64";
        case AexrtTileFlowConvAlgorithm::ImplicitGemm3x3_10x10_256x64: return "implicit_gemm_10x10_256x64";
        case AexrtTileFlowConvAlgorithm::ImplicitGemm3x3_10x10_512x64: return "implicit_gemm_10x10_512x64";
        case AexrtTileFlowConvAlgorithm::SplitK3x3_10x10_512x64: return "splitk_10x10_512x64";
        case AexrtTileFlowConvAlgorithm::SplitK3x3_20x20_256x64: return "splitk_20x20_256x64";
        case AexrtTileFlowConvAlgorithm::ImplicitGemm3x3_10x10_256x64Persistent: return "implicit_gemm_10x10_256x64_persistent";
        case AexrtTileFlowConvAlgorithm::ImplicitGemm3x3_10x10_256x64Oc2: return "implicit_gemm_10x10_256x64_oc2";
        case AexrtTileFlowConvAlgorithm::ImplicitGemm3x3_10x10_256x64Oc4: return "implicit_gemm_10x10_256x64_oc4";
        case AexrtTileFlowConvAlgorithm::ImplicitGemm3x3Stride2_80x80_32x64: return "stride2_implicit_gemm_80x80_32x64";
        case AexrtTileFlowConvAlgorithm::ImplicitGemm3x3Stride2_40x40_128x128: return "stride2_implicit_gemm_40x40_128x128";
        case AexrtTileFlowConvAlgorithm::ImplicitGemm3x3Stride2_20x20_128x128: return "stride2_implicit_gemm_20x20_128x128";
        case AexrtTileFlowConvAlgorithm::ImplicitGemm3x3Stride2_20x20_256x256: return "stride2_implicit_gemm_20x20_256x256";
        case AexrtTileFlowConvAlgorithm::ImplicitGemm3x3Stride2_10x10_256x256: return "stride2_implicit_gemm_10x10_256x256";
        case AexrtTileFlowConvAlgorithm::ImplicitGemm3x3Stride2_10x10_256x512: return "stride2_implicit_gemm_10x10_256x512";
        case AexrtTileFlowConvAlgorithm::Generic:
        default: return "generic";
    }
}

static bool can_use_shape_implicit_gemm_3x3(const AexrtConv2DDesc& desc, uint32_t out_dim) {
    return is_conv3x3_tiled_fast_path(desc) &&
        desc.out_h == out_dim && desc.out_w == out_dim &&
        desc.in_channels >= 32 && (desc.in_channels % 32) == 0 &&
        desc.out_channels >= 16 && (desc.out_channels % 16) == 0;
}

static bool can_use_exact_shape_implicit_gemm_3x3(const AexrtConv2DDesc& desc, uint32_t out_dim, uint32_t channels) {
    if (aexrt_env_flag("AEXRT_NATIVE_D3D12_DISABLE_EXACT_CHANNEL_IMPLICIT_GEMM_3X3")) return false;
    return can_use_shape_implicit_gemm_3x3(desc, out_dim) &&
        desc.in_channels == channels &&
        desc.out_channels == channels;
}

static bool can_use_exact_io_shape_implicit_gemm_3x3(
    const AexrtConv2DDesc& desc,
    uint32_t out_dim,
    uint32_t in_channels,
    uint32_t out_channels) {
    if (aexrt_env_flag("AEXRT_NATIVE_D3D12_DISABLE_EXACT_CHANNEL_IMPLICIT_GEMM_3X3")) return false;
    return can_use_shape_implicit_gemm_3x3(desc, out_dim) &&
        desc.in_channels == in_channels &&
        desc.out_channels == out_channels;
}

static bool can_use_exact_stride2_shape_implicit_gemm_3x3(
    const AexrtConv2DDesc& desc,
    uint32_t out_dim,
    uint32_t in_channels,
    uint32_t out_channels) {
    if (aexrt_env_flag("AEXRT_NATIVE_D3D12_DISABLE_EXACT_STRIDE2_IMPLICIT_GEMM_3X3")) return false;
    if (!aexrt_env_flag("AEXRT_NATIVE_D3D12_ENABLE_EXPERIMENTAL_EXACT_STRIDE2_IMPLICIT_GEMM_3X3") &&
        !aexrt_env_flag("AEXRT_NATIVE_D3D12_FORCE_EXACT_STRIDE2_IMPLICIT_GEMM_3X3")) return false;
    return is_conv3x3_stride2_tiled_fast_path(desc) &&
        desc.out_h == out_dim && desc.out_w == out_dim &&
        desc.in_channels == in_channels &&
        desc.out_channels == out_channels;
}

static bool should_use_splitk_conv3x3_10x10_512x64_silu(const AexrtConv2DDesc& desc) {
    if (aexrt_env_flag("AEXRT_NATIVE_D3D12_DISABLE_SPLITK_10X10_512X64_CONV3X3_SILU")) return false;
    return desc.batch >= 1 &&
        desc.in_channels == 512 &&
        desc.in_h == 10 &&
        desc.in_w == 10 &&
        desc.out_channels == 64 &&
        desc.out_h == 10 &&
        desc.out_w == 10 &&
        desc.kernel_h == 3 &&
        desc.kernel_w == 3 &&
        desc.stride_h == 1 &&
        desc.stride_w == 1 &&
        desc.pad_top == 1 &&
        desc.pad_left == 1 &&
        desc.dilation_h == 1 &&
        desc.dilation_w == 1 &&
        desc.groups == 1;
}

static bool should_use_splitk_conv3x3_20x20_256x64_silu(const AexrtConv2DDesc& desc) {
    if (aexrt_env_flag("AEXRT_NATIVE_D3D12_DISABLE_SPLITK_20X20_256X64_CONV3X3_SILU")) return false;
    if (!aexrt_env_flag("AEXRT_NATIVE_D3D12_ENABLE_EXPERIMENTAL_SPLITK_20X20_256X64_CONV3X3_SILU") &&
        !aexrt_env_flag("AEXRT_NATIVE_D3D12_FORCE_SPLITK_20X20_256X64_CONV3X3_SILU")) return false;
    return desc.batch >= 1 &&
        desc.in_channels == 256 &&
        desc.in_h == 20 &&
        desc.in_w == 20 &&
        desc.out_channels == 64 &&
        desc.out_h == 20 &&
        desc.out_w == 20 &&
        desc.kernel_h == 3 &&
        desc.kernel_w == 3 &&
        desc.stride_h == 1 &&
        desc.stride_w == 1 &&
        desc.pad_top == 1 &&
        desc.pad_left == 1 &&
        desc.dilation_h == 1 &&
        desc.dilation_w == 1 &&
        desc.groups == 1;
}

static bool should_use_splitk_conv3x3s2_10x10_256x512_silu(const AexrtConv2DDesc& desc) {
    if (aexrt_env_flag("AEXRT_NATIVE_D3D12_DISABLE_SPLITK_STRIDE2_10X10_256X512_CONV3X3_SILU")) return false;
    if (!aexrt_env_flag("AEXRT_NATIVE_D3D12_ENABLE_EXPERIMENTAL_SPLITK_STRIDE2_10X10_256X512_CONV3X3_SILU") &&
        !aexrt_env_flag("AEXRT_NATIVE_D3D12_FORCE_SPLITK_STRIDE2_10X10_256X512_CONV3X3_SILU")) return false;
    return desc.batch >= 1 &&
        desc.in_channels == 256 &&
        desc.in_h == 20 &&
        desc.in_w == 20 &&
        desc.out_channels == 512 &&
        desc.out_h == 10 &&
        desc.out_w == 10 &&
        desc.kernel_h == 3 &&
        desc.kernel_w == 3 &&
        desc.stride_h == 2 &&
        desc.stride_w == 2 &&
        desc.pad_top == 1 &&
        desc.pad_left == 1 &&
        desc.dilation_h == 1 &&
        desc.dilation_w == 1 &&
        desc.groups == 1;
}

static AexrtTileFlowConvAlgorithm plan_tileflow_conv(const AexrtConv2DDesc& desc, bool silu) {
    if (is_conv1x1_fast_path(desc)) return AexrtTileFlowConvAlgorithm::Conv1x1;
    if (!silu) return AexrtTileFlowConvAlgorithm::Generic;
    if (should_use_conv6x6_stride2_direct_pack4_silu(desc)) {
        return AexrtTileFlowConvAlgorithm::Spatial6x6Stride2DirectPack4;
    }
    if (should_use_conv3x3_silu_winograd_f2x2(desc)) {
        return AexrtTileFlowConvAlgorithm::WinogradF2x2_3x3;
    }
    if (should_use_conv3x3_silu_direct_pack4_packed_weight_pos2(desc)) {
        return AexrtTileFlowConvAlgorithm::Spatial3x3DirectPack4PackedWeightPos2;
    }
    if (should_use_conv3x3_silu_tileflow_spatial_exact(desc)) {
        return desc.out_h == 40
            ? AexrtTileFlowConvAlgorithm::TileFlowSpatial3x3_40x40_128x64
            : AexrtTileFlowConvAlgorithm::TileFlowSpatial3x3_20x20_256x64;
    }
    if (should_use_conv3x3_stride2_pack4_silu(desc)) {
        return AexrtTileFlowConvAlgorithm::Spatial3x3Stride2Pack4;
    }
    if (should_use_conv3x3_stride2_persistent_tile16_silu(desc)) {
        return AexrtTileFlowConvAlgorithm::Spatial3x3Stride2PersistentTile16;
    }
    if (should_use_conv3x3_stride2_direct_pack4_packed_weight_oc8_silu(desc)) {
        return AexrtTileFlowConvAlgorithm::Spatial3x3Stride2DirectPack4PackedWeightOc8;
    }
    if (should_use_conv3x3_stride2_direct_pack4_packed_weight_pos2_silu(desc)) {
        return AexrtTileFlowConvAlgorithm::Spatial3x3Stride2DirectPack4PackedWeightPos2;
    }
    if (should_use_conv3x3_stride2_direct_pack4_10x10_256x512_interior_silu(desc)) {
        return AexrtTileFlowConvAlgorithm::Spatial3x3Stride2DirectPack4_10x10_256x512Interior;
    }
    if (should_use_conv3x3_stride2_direct_pack4_packed_weight_silu(desc)) {
        return AexrtTileFlowConvAlgorithm::Spatial3x3Stride2DirectPack4PackedWeight;
    }
    if (should_use_conv3x3_stride2_direct_pack4_exact_silu(desc)) {
        return AexrtTileFlowConvAlgorithm::Spatial3x3Stride2DirectPack4Exact;
    }
    if (should_use_conv3x3_stride2_direct_pack8_silu(desc)) {
        return AexrtTileFlowConvAlgorithm::Spatial3x3Stride2DirectPack8;
    }
    if (should_use_splitk_conv3x3s2_10x10_256x512_silu(desc)) {
        return AexrtTileFlowConvAlgorithm::SplitK3x3Stride2_10x10_256x512;
    }
    if (should_use_conv3x3_stride2_direct_pack4_silu(desc)) {
        return AexrtTileFlowConvAlgorithm::Spatial3x3Stride2DirectPack4;
    }
    if (should_use_conv3x3_direct_pack4_silu(desc)) {
        return AexrtTileFlowConvAlgorithm::Spatial3x3DirectPack4;
    }
    if (should_use_splitk_conv3x3_10x10_512x64_silu(desc)) {
        return AexrtTileFlowConvAlgorithm::SplitK3x3_10x10_512x64;
    }
    if (should_use_splitk_conv3x3_20x20_256x64_silu(desc)) {
        return AexrtTileFlowConvAlgorithm::SplitK3x3_20x20_256x64;
    }
    if (!aexrt_env_flag("AEXRT_NATIVE_D3D12_DISABLE_IMPLICIT_GEMM_3X3") &&
        !aexrt_env_flag("AEXRT_NATIVE_D3D12_DISABLE_IMPLICIT_GEMM_STRIDE2_3X3") &&
        desc.stride_h == 2 && desc.stride_w == 2) {
        if (can_use_exact_stride2_shape_implicit_gemm_3x3(desc, 80, 32, 64)) {
            return AexrtTileFlowConvAlgorithm::ImplicitGemm3x3Stride2_80x80_32x64;
        }
        if (can_use_exact_stride2_shape_implicit_gemm_3x3(desc, 40, 128, 128)) {
            return AexrtTileFlowConvAlgorithm::ImplicitGemm3x3Stride2_40x40_128x128;
        }
        if (can_use_exact_stride2_shape_implicit_gemm_3x3(desc, 20, 128, 128)) {
            return AexrtTileFlowConvAlgorithm::ImplicitGemm3x3Stride2_20x20_128x128;
        }
        if (can_use_exact_stride2_shape_implicit_gemm_3x3(desc, 20, 256, 256)) {
            return AexrtTileFlowConvAlgorithm::ImplicitGemm3x3Stride2_20x20_256x256;
        }
        if (can_use_exact_stride2_shape_implicit_gemm_3x3(desc, 10, 256, 256)) {
            return AexrtTileFlowConvAlgorithm::ImplicitGemm3x3Stride2_10x10_256x256;
        }
        if (can_use_exact_stride2_shape_implicit_gemm_3x3(desc, 10, 256, 512)) {
            return AexrtTileFlowConvAlgorithm::ImplicitGemm3x3Stride2_10x10_256x512;
        }
    }
    if (!aexrt_env_flag("AEXRT_NATIVE_D3D12_DISABLE_DIRECT_10X10_64OC_CONV3X3_SILU") &&
        is_conv3x3_tiled_fast_path(desc) &&
        desc.out_h == 10 &&
        desc.out_w == 10 &&
        desc.out_channels == 64 &&
        desc.stride_h == 1 &&
        desc.stride_w == 1) {
        return AexrtTileFlowConvAlgorithm::Spatial3x3;
    }
    if (!aexrt_env_flag("AEXRT_NATIVE_D3D12_DISABLE_SHAPE_IMPLICIT_GEMM_3X3") &&
        !aexrt_env_flag("AEXRT_NATIVE_D3D12_DISABLE_SHAPE40_IMPLICIT_GEMM_3X3") &&
        can_use_shape_implicit_gemm_3x3(desc, 40)) {
        if (can_use_exact_shape_implicit_gemm_3x3(desc, 40, 64) &&
            (aexrt_env_flag("AEXRT_NATIVE_D3D12_ENABLE_EXACT_40X40_64X64_IMPLICIT_GEMM_3X3") ||
                aexrt_env_flag("AEXRT_NATIVE_D3D12_FORCE_SHAPE40_IMPLICIT_GEMM_3X3")) &&
            !aexrt_env_flag("AEXRT_NATIVE_D3D12_DISABLE_EXACT_40X40_64X64_IMPLICIT_GEMM_3X3")) {
            return AexrtTileFlowConvAlgorithm::ImplicitGemm3x3_40x40_64x64;
        }
        if (aexrt_env_flag("AEXRT_NATIVE_D3D12_ENABLE_SHAPE40_IMPLICIT_GEMM_3X3") ||
            aexrt_env_flag("AEXRT_NATIVE_D3D12_FORCE_SHAPE40_IMPLICIT_GEMM_3X3")) {
            return AexrtTileFlowConvAlgorithm::ImplicitGemm3x3_40x40;
        }
    }
    if (should_use_conv3x3_implicit_gemm_silu(desc)) {
        if (desc.stride_h == 2 && desc.stride_w == 2) {
            if (can_use_exact_stride2_shape_implicit_gemm_3x3(desc, 80, 32, 64)) {
                return AexrtTileFlowConvAlgorithm::ImplicitGemm3x3Stride2_80x80_32x64;
            }
            if (can_use_exact_stride2_shape_implicit_gemm_3x3(desc, 40, 128, 128)) {
                return AexrtTileFlowConvAlgorithm::ImplicitGemm3x3Stride2_40x40_128x128;
            }
            if (can_use_exact_stride2_shape_implicit_gemm_3x3(desc, 20, 128, 128)) {
                return AexrtTileFlowConvAlgorithm::ImplicitGemm3x3Stride2_20x20_128x128;
            }
            if (can_use_exact_stride2_shape_implicit_gemm_3x3(desc, 20, 256, 256)) {
                return AexrtTileFlowConvAlgorithm::ImplicitGemm3x3Stride2_20x20_256x256;
            }
            if (can_use_exact_stride2_shape_implicit_gemm_3x3(desc, 10, 256, 256)) {
                return AexrtTileFlowConvAlgorithm::ImplicitGemm3x3Stride2_10x10_256x256;
            }
            if (can_use_exact_stride2_shape_implicit_gemm_3x3(desc, 10, 256, 512)) {
                return AexrtTileFlowConvAlgorithm::ImplicitGemm3x3Stride2_10x10_256x512;
            }
        }
        if (!aexrt_env_flag("AEXRT_NATIVE_D3D12_DISABLE_SHAPE_IMPLICIT_GEMM_3X3") &&
            is_conv3x3_tiled_fast_path(desc)) {
            if (can_use_shape_implicit_gemm_3x3(desc, 20) &&
                !aexrt_env_flag("AEXRT_NATIVE_D3D12_DISABLE_SHAPE20_IMPLICIT_GEMM_3X3")) {
                if (can_use_exact_io_shape_implicit_gemm_3x3(desc, 20, 128, 64) &&
                    !aexrt_env_flag("AEXRT_NATIVE_D3D12_DISABLE_EXACT_20X20_128X64_IMPLICIT_GEMM_3X3")) {
                    return AexrtTileFlowConvAlgorithm::ImplicitGemm3x3_20x20_128x64;
                }
                if (can_use_exact_io_shape_implicit_gemm_3x3(desc, 20, 256, 64) &&
                    (aexrt_env_flag("AEXRT_NATIVE_D3D12_ENABLE_EXPERIMENTAL_EXACT_20X20_256X64_IMPLICIT_GEMM_3X3") ||
                        aexrt_env_flag("AEXRT_NATIVE_D3D12_FORCE_EXACT_20X20_256X64_IMPLICIT_GEMM_3X3")) &&
                    !aexrt_env_flag("AEXRT_NATIVE_D3D12_DISABLE_EXACT_20X20_256X64_IMPLICIT_GEMM_3X3")) {
                    return AexrtTileFlowConvAlgorithm::ImplicitGemm3x3_20x20_256x64;
                }
                if (can_use_exact_shape_implicit_gemm_3x3(desc, 20, 64) &&
                    !aexrt_env_flag("AEXRT_NATIVE_D3D12_DISABLE_EXACT_20X20_64X64_IMPLICIT_GEMM_3X3")) {
                    return AexrtTileFlowConvAlgorithm::ImplicitGemm3x3_20x20_64x64;
                }
                return AexrtTileFlowConvAlgorithm::ImplicitGemm3x3_20x20;
            }
            if (can_use_shape_implicit_gemm_3x3(desc, 10) &&
                !aexrt_env_flag("AEXRT_NATIVE_D3D12_DISABLE_SHAPE10_IMPLICIT_GEMM_3X3")) {
                if (can_use_exact_io_shape_implicit_gemm_3x3(desc, 10, 256, 64) &&
                    !aexrt_env_flag("AEXRT_NATIVE_D3D12_DISABLE_EXACT_10X10_256X64_IMPLICIT_GEMM_3X3")) {
                    const bool unstable_experimental =
                        aexrt_env_flag("AEXRT_NATIVE_D3D12_ENABLE_UNSTABLE_EXPERIMENTAL_KERNELS");
                    if (unstable_experimental &&
                        (aexrt_env_flag("AEXRT_NATIVE_D3D12_ENABLE_OC4_10X10_256X64_IMPLICIT_GEMM_3X3") ||
                            aexrt_env_flag("AEXRT_NATIVE_D3D12_FORCE_OC4_10X10_256X64_IMPLICIT_GEMM_3X3")) &&
                        !aexrt_env_flag("AEXRT_NATIVE_D3D12_DISABLE_OC4_10X10_256X64_IMPLICIT_GEMM_3X3")) {
                        return AexrtTileFlowConvAlgorithm::ImplicitGemm3x3_10x10_256x64Oc4;
                    }
                    if (unstable_experimental &&
                        (aexrt_env_flag("AEXRT_NATIVE_D3D12_ENABLE_OC2_10X10_256X64_IMPLICIT_GEMM_3X3") ||
                            aexrt_env_flag("AEXRT_NATIVE_D3D12_FORCE_OC2_10X10_256X64_IMPLICIT_GEMM_3X3")) &&
                        !aexrt_env_flag("AEXRT_NATIVE_D3D12_DISABLE_OC2_10X10_256X64_IMPLICIT_GEMM_3X3")) {
                        return AexrtTileFlowConvAlgorithm::ImplicitGemm3x3_10x10_256x64Oc2;
                    }
                    if ((aexrt_env_flag("AEXRT_NATIVE_D3D12_ENABLE_PERSISTENT_10X10_256X64_IMPLICIT_GEMM_3X3") ||
                            aexrt_env_flag("AEXRT_NATIVE_D3D12_FORCE_PERSISTENT_10X10_256X64_IMPLICIT_GEMM_3X3")) &&
                        !aexrt_env_flag("AEXRT_NATIVE_D3D12_DISABLE_PERSISTENT_10X10_256X64_IMPLICIT_GEMM_3X3")) {
                        return AexrtTileFlowConvAlgorithm::ImplicitGemm3x3_10x10_256x64Persistent;
                    }
                    return AexrtTileFlowConvAlgorithm::ImplicitGemm3x3_10x10_256x64;
                }
                if (can_use_exact_io_shape_implicit_gemm_3x3(desc, 10, 512, 64) &&
                    (aexrt_env_flag("AEXRT_NATIVE_D3D12_ENABLE_EXPERIMENTAL_EXACT_10X10_512X64_IMPLICIT_GEMM_3X3") ||
                        aexrt_env_flag("AEXRT_NATIVE_D3D12_FORCE_EXACT_10X10_512X64_IMPLICIT_GEMM_3X3")) &&
                    !aexrt_env_flag("AEXRT_NATIVE_D3D12_DISABLE_EXACT_10X10_512X64_IMPLICIT_GEMM_3X3")) {
                    return AexrtTileFlowConvAlgorithm::ImplicitGemm3x3_10x10_512x64;
                }
                if (can_use_exact_shape_implicit_gemm_3x3(desc, 10, 128) &&
                    !aexrt_env_flag("AEXRT_NATIVE_D3D12_DISABLE_EXACT_10X10_128X128_IMPLICIT_GEMM_3X3")) {
                    return AexrtTileFlowConvAlgorithm::ImplicitGemm3x3_10x10_128x128;
                }
                return AexrtTileFlowConvAlgorithm::ImplicitGemm3x3_10x10;
            }
        }
        return AexrtTileFlowConvAlgorithm::ImplicitGemm3x3;
    }
    if (!is_conv3x3_tiled_fast_path(desc)) return AexrtTileFlowConvAlgorithm::Generic;
    if (should_use_conv3x3_pack8_silu(desc)) return AexrtTileFlowConvAlgorithm::Spatial3x3Pack8;
    if (should_use_conv3x3_pack4_silu(desc)) return AexrtTileFlowConvAlgorithm::Spatial3x3Pack4;
    return AexrtTileFlowConvAlgorithm::Spatial3x3;
}

static bool can_use_conv3x3s2_native_fp16(
    AexrtDevice* device,
    const AexrtConv2DDesc& desc,
    bool silu) {
    if (!device || !silu) return false;
    if (!device->native_fp16_supported || !device->dxc_available ||
        device->highest_shader_model < D3D_SHADER_MODEL_6_2) return false;
    return is_conv3x3_stride2_tiled_fast_path(desc) && desc.in_channels >= 32u &&
        (desc.in_channels % 4u) == 0 && (desc.out_channels % 4u) == 0;
}

static bool is_conv3x3s2_native_fp16_position_pair_40x40_256x256_shape(
    const AexrtConv2DDesc& desc) {
    return desc.batch == 1u && desc.in_channels == 256u &&
        desc.in_h == 40u && desc.in_w == 40u &&
        desc.out_channels == 256u && desc.out_h == 20u && desc.out_w == 20u &&
        desc.kernel_h == 3u && desc.kernel_w == 3u &&
        desc.stride_h == 2u && desc.stride_w == 2u &&
        desc.pad_top == 1u && desc.pad_left == 1u &&
        desc.dilation_h == 1u && desc.dilation_w == 1u && desc.groups == 1u;
}

static bool can_use_conv3x3s2_native_fp16_position_pair_40x40_256x256(
    AexrtDevice* device,
    const AexrtConv2DDesc& desc,
    bool silu) {
    return device && silu && device->native_fp16_supported && device->dxc_available &&
        device->highest_shader_model >= D3D_SHADER_MODEL_6_2 &&
        is_conv3x3s2_native_fp16_position_pair_40x40_256x256_shape(desc);
}

static bool is_conv3x3s2_native_fp16_position_quartet_80x80_128x128_shape(
    const AexrtConv2DDesc& desc) {
    return desc.batch == 1u && desc.in_channels == 128u &&
        desc.in_h == 80u && desc.in_w == 80u &&
        desc.out_channels == 128u && desc.out_h == 40u && desc.out_w == 40u &&
        desc.kernel_h == 3u && desc.kernel_w == 3u &&
        desc.stride_h == 2u && desc.stride_w == 2u &&
        desc.pad_top == 1u && desc.pad_left == 1u &&
        desc.dilation_h == 1u && desc.dilation_w == 1u && desc.groups == 1u;
}

static bool can_use_conv3x3s2_native_fp16_position_quartet_80x80_128x128(
    AexrtDevice* device,
    const AexrtConv2DDesc& desc,
    bool silu) {
    return device && silu && device->native_fp16_supported && device->dxc_available &&
        device->highest_shader_model >= D3D_SHADER_MODEL_6_2 &&
        is_conv3x3s2_native_fp16_position_quartet_80x80_128x128_shape(desc);
}

static bool can_use_conv3x3_native_fp16_pos2_40x40_64x64(
    AexrtDevice* device,
    const AexrtConv2DDesc& desc,
    bool silu) {
    if (!device || !silu || !device->native_fp16_supported || !device->dxc_available ||
        device->highest_shader_model < D3D_SHADER_MODEL_6_2) return false;
    return desc.batch >= 1u && is_conv3x3_tiled_fast_path(desc) &&
        desc.in_channels == 64u && desc.out_channels == 64u &&
        desc.in_h == 40u && desc.in_w == 40u &&
        desc.out_h == 40u && desc.out_w == 40u;
}

static bool is_measured_conv3x3s2_native_fp16_shape(const AexrtConv2DDesc& desc) {
    return (desc.out_h == 10u && desc.out_w == 10u) ||
        (desc.out_h == 20u && desc.out_w == 20u && desc.out_channels <= 128u);
}

static bool can_use_conv1x1_native_fp16_oc8_pos2(
    AexrtDevice* device,
    const AexrtConv2DDesc& desc) {
    if (!device || !device->native_fp16_supported || !device->dxc_available ||
        device->highest_shader_model < D3D_SHADER_MODEL_6_2) return false;
    const bool measured_spatial = desc.out_h == desc.out_w &&
        (desc.out_h == 10u || desc.out_h == 20u || desc.out_h == 40u || desc.out_h == 80u);
    return desc.batch == 1u && measured_spatial &&
        desc.in_channels >= 64u && desc.out_channels >= 64u &&
        (desc.in_channels % 4u) == 0 && (desc.out_channels % 8u) == 0 &&
        uint64_t(desc.out_h) * desc.out_w >= 100u &&
        desc.in_h == desc.out_h && desc.in_w == desc.out_w &&
        desc.kernel_h == 1u && desc.kernel_w == 1u &&
        desc.stride_h == 1u && desc.stride_w == 1u &&
        desc.pad_top == 0u && desc.pad_left == 0u &&
        desc.dilation_h == 1u && desc.dilation_w == 1u && desc.groups == 1u;
}

static bool should_use_conv3x3s2_native_fp16(
    AexrtDevice* device,
    const AexrtConv2DDesc& desc,
    bool silu) {
    if (aexrt_env_flag("AEXRT_NATIVE_D3D12_DISABLE_NATIVE_FP16_3X3") ||
        !can_use_conv3x3s2_native_fp16(device, desc, silu)) return false;
    const bool experimental_all =
        aexrt_env_flag("AEXRT_NATIVE_D3D12_ENABLE_NATIVE_FP16_3X3") ||
        aexrt_env_flag("AEXRT_NATIVE_D3D12_FORCE_NATIVE_FP16_3X3");
    if (!experimental_all && !is_measured_conv3x3s2_native_fp16_shape(desc)) return false;
    const uint32_t out_dim = aexrt_env_u32("AEXRT_NATIVE_D3D12_NATIVE_FP16_OUT_DIM");
    const uint32_t in_channels = aexrt_env_u32("AEXRT_NATIVE_D3D12_NATIVE_FP16_IN_CHANNELS");
    const uint32_t out_channels = aexrt_env_u32("AEXRT_NATIVE_D3D12_NATIVE_FP16_OUT_CHANNELS");
    return (out_dim == 0 || (desc.out_h == out_dim && desc.out_w == out_dim)) &&
        (in_channels == 0 || desc.in_channels == in_channels) &&
        (out_channels == 0 || desc.out_channels == out_channels);
}

static bool can_use_conv_int8(
    AexrtDevice* device,
    const AexrtConv2DDesc& desc,
    bool silu,
    uint32_t kernel_elems) {
    if (!aexrt_device_supports_int8_dot4(device)) return false;
    if (desc.groups != 1 || (desc.in_channels % 4u) != 0 || (desc.out_channels % 4u) != 0) return false;
    if (kernel_elems == 1u) {
        /* 1x1：k1s1 无 pad。 */
        if (desc.kernel_h != 1 || desc.kernel_w != 1 || desc.stride_h != 1 || desc.stride_w != 1 ||
            desc.pad_top != 0 || desc.pad_left != 0 || desc.dilation_h != 1 || desc.dilation_w != 1) return false;
        if ((desc.out_channels % 8u) != 0 || desc.in_h != desc.out_h || desc.in_w != desc.out_w) return false;
        return true;
    }
    if (kernel_elems == 9u) {
        if (desc.kernel_h != 3 || desc.kernel_w != 3 || desc.dilation_h != 1 || desc.dilation_w != 1 ||
            desc.pad_top != 1 || desc.pad_left != 1) return false;
        if (desc.stride_h == 2 && desc.stride_w == 2) {
            return desc.in_h >= desc.out_h * 2u - 1u && desc.in_w >= desc.out_w * 2u - 1u;
        }
        if (desc.stride_h != 1 || desc.stride_w != 1) return false;
        return desc.in_h == desc.out_h && desc.in_w == desc.out_w;
    }
    return false;
}

static AexrtTileFlowConvAlgorithm replay_conv_algorithm(
    AexrtDevice* device,
    const AexrtReplayCommand& command,
    const AexrtConv2DDesc& desc,
    bool silu) {
    const uint32_t max_algorithm = static_cast<uint32_t>(
        AexrtTileFlowConvAlgorithm::WinogradF4x4_3x3);
    if ((command.planned_flags & 1u) != 0 && command.planned_kernel <= max_algorithm) {
        const auto planned = static_cast<AexrtTileFlowConvAlgorithm>(command.planned_kernel);
        const bool activation_fp16_io = (command.planned_flags & ((1u << 2) | (1u << 3))) != 0;
        /* 新族 fail-closed 回退：设备/形状不满足时回落到既有安全算法，
         * 保持"引擎可执行"而非崩溃。回退统一走 plan_tileflow_conv：
         * 它对分组卷积/非快速路径形状返回 Generic（真正全形状安全），
         * 硬编码 pack4/stride2 基线在 groups>1 时同样越界（实测设备移除）。 */
        if (planned == AexrtTileFlowConvAlgorithm::Int8Dot4Conv1x1 &&
            !can_use_conv_int8(device, desc, silu, 1u)) {
            return plan_tileflow_conv(desc, silu);
        }
        if (planned == AexrtTileFlowConvAlgorithm::Int8Dot4Conv3x3 &&
            !can_use_conv_int8(device, desc, silu, 9u)) {
            return plan_tileflow_conv(desc, silu);
        }
        if (planned == AexrtTileFlowConvAlgorithm::Int8Dot4Conv3x3Stride2 &&
            !can_use_conv_int8(device, desc, silu, 9u)) {
            return plan_tileflow_conv(desc, silu);
        }
        if (planned == AexrtTileFlowConvAlgorithm::WinogradF4x4_3x3 &&
            (!can_use_conv3x3_silu_winograd_f4x4(desc) || silu == false)) {
            return plan_tileflow_conv(desc, silu);
        }
        if ((planned == AexrtTileFlowConvAlgorithm::WinogradF2x2_3x3 ||
             planned == AexrtTileFlowConvAlgorithm::WinogradF2x2_3x3Fp32Accum) &&
            (silu == false ||
             desc.kernel_h != 3 || desc.kernel_w != 3 ||
             desc.stride_h != 1 || desc.stride_w != 1 ||
             desc.pad_top != 1 || desc.pad_left != 1 ||
             desc.dilation_h != 1 || desc.dilation_w != 1 ||
             desc.groups != 1)) {
            /* Winograd F(2x2) 族（40/46）按 groups=1 的 3x3 s1 p1 d1 silu 布局寻址；
             * 分组卷积（实测 DYv11s cmd#139 groups=128）会越界 → 设备移除。
             * 与 enumerate_conv_candidates 的候选条件保持一致，fail-closed 回退。 */
            return plan_tileflow_conv(desc, silu);
        }
        if (planned == AexrtTileFlowConvAlgorithm::Conv1x1 &&
            !is_conv1x1_fast_path(desc)) {
            /* conv1x1 shader 忽略 groups（按 groups=1 权重布局寻址）：
             * 分组 1x1 会越界读权重。 */
            return plan_tileflow_conv(desc, silu);
        }
        if (planned == AexrtTileFlowConvAlgorithm::Spatial3x3Stride2NativeFp16PackedWeight &&
            !can_use_conv3x3s2_native_fp16(device, desc, silu)) {
            return plan_tileflow_conv(desc, silu);
        }
        if (planned == AexrtTileFlowConvAlgorithm::Spatial3x3Stride2NativeFp16PositionPair_40x40_256x256 &&
            !can_use_conv3x3s2_native_fp16_position_pair_40x40_256x256(device, desc, silu)) {
            return plan_tileflow_conv(desc, silu);
        }
        if (planned == AexrtTileFlowConvAlgorithm::Spatial3x3Stride2NativeFp16PositionQuartet_80x80_128x128 &&
            !can_use_conv3x3s2_native_fp16_position_quartet_80x80_128x128(device, desc, silu)) {
            return plan_tileflow_conv(desc, silu);
        }
        if (planned == AexrtTileFlowConvAlgorithm::Spatial3x3NativeFp16PackedWeightPos2_40x40_64x64 &&
            !activation_fp16_io &&
            !can_use_conv3x3_native_fp16_pos2_40x40_64x64(device, desc, silu)) {
            return plan_tileflow_conv(desc, silu);
        }
        if (planned == AexrtTileFlowConvAlgorithm::NativeFp16Conv1x1Oc8Pos2 &&
            !activation_fp16_io && !can_use_conv1x1_native_fp16_oc8_pos2(device, desc)) {
            return plan_tileflow_conv(desc, silu);
        }
        return planned;
    }
    if (should_use_conv3x3s2_native_fp16(device, desc, silu)) {
        return AexrtTileFlowConvAlgorithm::Spatial3x3Stride2NativeFp16PackedWeight;
    }
    if (command.planned_kernel <= max_algorithm) {
        return static_cast<AexrtTileFlowConvAlgorithm>(command.planned_kernel);
    }
    return plan_tileflow_conv(desc, silu);
}

/*
 * autotune 候选枚举：按 conv 形状与设备能力给出可尝试的算法 ID 列表。
 * 注意：权重打包布局由编译期算法决定，跨布局切换可能产生数值差异，
 * 调用方必须自行做数值门禁（如 detections 一致性校验）后再采纳结果。
 */
static uint32_t enumerate_conv_candidates(
    AexrtDevice* device,
    const AexrtConv2DDesc& desc,
    bool silu,
    uint32_t* out_ids,
    uint32_t cap) {
    if (!out_ids || cap == 0) return 0;
    uint32_t count = 0;
    auto push = [&](uint32_t id) {
        if (count < cap) out_ids[count++] = id;
    };
    const bool k3 = desc.kernel_h == 3 && desc.kernel_w == 3;
    const bool s2 = desc.stride_h == 2 && desc.stride_w == 2;
    const bool pad1 = desc.pad_top == 1 && desc.pad_left == 1;
    const bool linear = desc.dilation_h == 1 && desc.dilation_w == 1 && desc.groups == 1;

    if (desc.kernel_h == 1 && desc.kernel_w == 1 && !s2 && linear) {
        /* conv1x1 族（1/45/51）均按 groups=1 权重布局寻址，分组 1x1 只走 Generic。 */
        push(1);
        if (device && can_use_conv1x1_native_fp16_oc8_pos2(device, desc)) push(45);
        if (device && can_use_conv_int8(device, desc, silu, 1u)) push(51);
        return count;
    }
    if (desc.kernel_h == 6 && desc.kernel_w == 6 && s2) {
        push(42);
        push(0);
        return count;
    }
    if (k3 && linear && pad1 && !s2 && silu) {
        push(3);  /* pack4：通用基线 */
        push(4);  /* pack8 */
        push(2);  /* spatial3x3 */
        push(40); /* winograd f2x2 */
        push(46); /* winograd fp32 accum */
        if (can_use_conv3x3_silu_winograd_f4x4(desc)) push(54); /* winograd f4x4 */
        if (can_use_shape_implicit_gemm_3x3(desc, 40)) { push(6); push(9); }
        if (can_use_shape_implicit_gemm_3x3(desc, 20)) { push(7); push(10); push(12); push(26); }
        if (can_use_shape_implicit_gemm_3x3(desc, 10)) { push(8); push(11); push(13); push(14); push(15); push(16); push(27); }
        /* 形状特化算法必须通过各自的判定函数，盲切会越界（GPU 崩溃）。 */
        if (should_use_conv3x3_silu_direct_pack4_packed_weight_pos2(desc)) push(39);
        if (device && can_use_conv3x3_native_fp16_pos2_40x40_64x64(device, desc, silu)) push(44);
        if (device && can_use_conv_int8(device, desc, silu, 9u)) push(52);
        push(25);
        push(0);
        return count;
    }
    if (k3 && linear && s2 && silu) {
        push(24); /* stride2 direct pack4：通用基线 */
        /* 形状特化算法必须通过各自的判定函数，盲切会越界（GPU 崩溃）。 */
        if (should_use_conv3x3_stride2_direct_pack8_silu(desc)) push(30);
        if (should_use_conv3x3_stride2_direct_pack4_packed_weight_silu(desc)) push(32);
        if (should_use_conv3x3_stride2_direct_pack4_packed_weight_pos2_silu(desc)) push(33);
        if (should_use_conv3x3_stride2_direct_pack4_packed_weight_oc8_silu(desc)) push(34);
        if (should_use_conv3x3_stride2_direct_pack4_exact_silu(desc)) push(31);
        if (should_use_conv3x3_stride2_direct_pack4_10x10_256x512_interior_silu(desc)) push(35);
        if (desc.out_h == 80 && desc.out_w == 80) { push(18); push(48); push(49); push(50); }
        if (desc.out_h == 40 && desc.out_w == 40) { push(19); push(47); }
        if (desc.out_h == 20 && desc.out_w == 20) { push(20); push(21); }
        if (desc.out_h == 10 && desc.out_w == 10) { push(22); push(23); }
        if (device && can_use_conv3x3s2_native_fp16(device, desc, silu)) push(43);
        if (device && can_use_conv_int8(device, desc, silu, 9u)) push(53);
        push(0);
        return count;
    }
    push(0);
    return count;
}

static HRESULT ensure_concat_conv1x1_pipeline(AexrtDevice* ctx, bool silu) {
    ComPtr<ID3D12PipelineState>& target = silu ? ctx->concat_conv1x1_silu_pso : ctx->concat_conv1x1_linear_pso;
    if (target) {
        return S_OK;
    }
    const char* shader_source = R"(
StructuredBuffer<float> input0 : register(t0);
StructuredBuffer<float> input1 : register(t1);
StructuredBuffer<float> input2 : register(t2);
StructuredBuffer<float> input3 : register(t3);
StructuredBuffer<float> input4 : register(t4);
StructuredBuffer<float> input5 : register(t5);
StructuredBuffer<float> input6 : register(t6);
StructuredBuffer<float> input7 : register(t7);
StructuredBuffer<float> weight : register(t8);
StructuredBuffer<float> bias : register(t9);
RWStructuredBuffer<float> output : register(u0);
cbuffer AexrtConcatConvConstants : register(b0) {
    uint batch;
    uint total_in_channels;
    uint height;
    uint width;
    uint out_channels;
    uint out_h;
    uint out_w;
    uint input_count;
    uint c0;
    uint c1;
    uint c2;
    uint c3;
    uint c4;
    uint c5;
    uint c6;
    uint c7;
};
float read_input(uint branch, uint idx) {
    if (branch == 0) return input0[idx];
    if (branch == 1) return input1[idx];
    if (branch == 2) return input2[idx];
    if (branch == 3) return input3[idx];
    if (branch == 4) return input4[idx];
    if (branch == 5) return input5[idx];
    if (branch == 6) return input6[idx];
    return input7[idx];
}
uint branch_channels(uint branch) {
    if (branch == 0) return c0;
    if (branch == 1) return c1;
    if (branch == 2) return c2;
    if (branch == 3) return c3;
    if (branch == 4) return c4;
    if (branch == 5) return c5;
    if (branch == 6) return c6;
    return c7;
}
[numthreads(256, 1, 1)]
void main(uint3 tid : SV_DispatchThreadID) {
    uint idx = tid.x;
    uint total = batch * out_channels * out_h * out_w;
    if (idx >= total) {
        return;
    }
    uint x = idx % out_w;
    uint t = idx / out_w;
    uint y = t % out_h;
    t = t / out_h;
    uint oc = t % out_channels;
    uint n = t / out_channels;
    uint spatial = y * width + x;

    float acc = bias[oc];
    uint channel_base = 0;
    [unroll]
    for (uint b = 0; b < 8; ++b) {
        uint channels = branch_channels(b);
        if (b >= input_count || channels == 0) {
            continue;
        }
        for (uint c = 0; c < channels; ++c) {
            uint input_idx = (n * channels + c) * height * width + spatial;
            uint weight_idx = oc * total_in_channels + channel_base + c;
            acc += read_input(b, input_idx) * weight[weight_idx];
        }
        channel_base += channels;
    }
#ifdef AEXRT_SILU
    acc = acc / (1.0 + exp(-acc));
#endif
    output[idx] = acc;
}
)";
    D3D_SHADER_MACRO silu_macros[] = {
        {"AEXRT_SILU", "1"},
        {nullptr, nullptr},
    };
    ComPtr<ID3DBlob> shader;
    ComPtr<ID3DBlob> errors;
    HRESULT hr = D3DCompile(shader_source, std::strlen(shader_source), "aexrt_concat_conv1x1_float32", silu ? silu_macros : nullptr, nullptr, "main", "cs_5_0", D3DCOMPILE_OPTIMIZATION_LEVEL3, 0, &shader, &errors);
    if (FAILED(hr)) return hr;

    if (!ctx->concat_conv_root_signature) {
        D3D12_DESCRIPTOR_RANGE srv_range{};
        srv_range.RangeType = D3D12_DESCRIPTOR_RANGE_TYPE_SRV;
        srv_range.NumDescriptors = 10;
        srv_range.BaseShaderRegister = 0;
        srv_range.OffsetInDescriptorsFromTableStart = D3D12_DESCRIPTOR_RANGE_OFFSET_APPEND;
        D3D12_DESCRIPTOR_RANGE uav_range{};
        uav_range.RangeType = D3D12_DESCRIPTOR_RANGE_TYPE_UAV;
        uav_range.NumDescriptors = 1;
        uav_range.BaseShaderRegister = 0;
        uav_range.OffsetInDescriptorsFromTableStart = D3D12_DESCRIPTOR_RANGE_OFFSET_APPEND;

        D3D12_ROOT_PARAMETER params[3]{};
        params[0].ParameterType = D3D12_ROOT_PARAMETER_TYPE_DESCRIPTOR_TABLE;
        params[0].DescriptorTable.NumDescriptorRanges = 1;
        params[0].DescriptorTable.pDescriptorRanges = &srv_range;
        params[1].ParameterType = D3D12_ROOT_PARAMETER_TYPE_DESCRIPTOR_TABLE;
        params[1].DescriptorTable.NumDescriptorRanges = 1;
        params[1].DescriptorTable.pDescriptorRanges = &uav_range;
        params[2].ParameterType = D3D12_ROOT_PARAMETER_TYPE_32BIT_CONSTANTS;
        params[2].Constants.ShaderRegister = 0;
        params[2].Constants.Num32BitValues = 16;

        D3D12_ROOT_SIGNATURE_DESC root_desc{};
        root_desc.NumParameters = 3;
        root_desc.pParameters = params;
        ComPtr<ID3DBlob> root_blob;
        hr = D3D12SerializeRootSignature(&root_desc, D3D_ROOT_SIGNATURE_VERSION_1, &root_blob, &errors);
        if (FAILED(hr)) return hr;
        hr = ctx->device->CreateRootSignature(0, root_blob->GetBufferPointer(), root_blob->GetBufferSize(), IID_PPV_ARGS(&ctx->concat_conv_root_signature));
        if (FAILED(hr)) return hr;
    }

    D3D12_COMPUTE_PIPELINE_STATE_DESC pso{};
    pso.pRootSignature = ctx->concat_conv_root_signature.Get();
    pso.CS.pShaderBytecode = shader->GetBufferPointer();
    pso.CS.BytecodeLength = shader->GetBufferSize();
    return aexrt_create_compute_pipeline_state(ctx, &pso, IID_PPV_ARGS(&target));
}

/* vec4 变体：thread = (oc4, 像素)。旧 kernel 每线程串行通道循环且权重为
 * 跨 total_in 步长的标量 gather（warp 内互不 coalesce），是 concat 家族
 * 长期只跑出个位数 GB/s 的根因。这里把 4 个输出通道打包进一个线程，
 * 权重改为连续 float4 读并被 4 个 oc 摊薄；输入保持标量但 warp 内相邻
 * 线程读相邻像素，硬件 coalescing 仍然成立。要求 oc 与各分支通道数
 * 都是 4 的倍数（YOLO 通道恒满足），否则调用方回退旧 kernel。 */
static HRESULT ensure_concat_conv1x1_vec4_pipeline(AexrtDevice* ctx, bool silu) {
    ComPtr<ID3D12PipelineState>& target = silu ? ctx->concat_conv1x1_vec4_silu_pso : ctx->concat_conv1x1_vec4_linear_pso;
    if (ctx->concat_conv_root_signature && target) {
        return S_OK;
    }
    if (!ctx->concat_conv_root_signature) {
        HRESULT hr = ensure_concat_conv1x1_pipeline(ctx, silu);
        if (FAILED(hr)) return hr;
    }
    const char* shader_source = R"(
StructuredBuffer<float> input0 : register(t0);
StructuredBuffer<float> input1 : register(t1);
StructuredBuffer<float> input2 : register(t2);
StructuredBuffer<float> input3 : register(t3);
StructuredBuffer<float> input4 : register(t4);
StructuredBuffer<float> input5 : register(t5);
StructuredBuffer<float> input6 : register(t6);
StructuredBuffer<float> input7 : register(t7);
StructuredBuffer<float4> weight4 : register(t8);
StructuredBuffer<float> bias : register(t9);
RWStructuredBuffer<float> output : register(u0);
cbuffer AexrtConcatConvConstants : register(b0) {
    uint batch;
    uint total_in_channels;
    uint height;
    uint width;
    uint out_channels;
    uint out_h;
    uint out_w;
    uint input_count;
    uint c0;
    uint c1;
    uint c2;
    uint c3;
    uint c4;
    uint c5;
    uint c6;
    uint c7;
};
float read_input(uint branch, uint idx) {
    if (branch == 0) return input0[idx];
    if (branch == 1) return input1[idx];
    if (branch == 2) return input2[idx];
    if (branch == 3) return input3[idx];
    if (branch == 4) return input4[idx];
    if (branch == 5) return input5[idx];
    if (branch == 6) return input6[idx];
    return input7[idx];
}
uint branch_channels(uint branch) {
    if (branch == 0) return c0;
    if (branch == 1) return c1;
    if (branch == 2) return c2;
    if (branch == 3) return c3;
    if (branch == 4) return c4;
    if (branch == 5) return c5;
    if (branch == 6) return c6;
    return c7;
}
[numthreads(128, 1, 1)]
void main(uint3 tid : SV_DispatchThreadID) {
    uint idx = tid.x;
    uint oc_blocks = out_channels / 4u;
    uint total = batch * oc_blocks * out_h * out_w;
    if (idx >= total) {
        return;
    }
    uint x = idx % out_w;
    uint t = idx / out_w;
    uint y = t % out_h;
    t = t / out_h;
    uint oc4 = t % oc_blocks;
    uint n = t / oc_blocks;
    uint spatial = y * width + x;
    uint plane = height * width;

    float4 acc = float4(
        bias[oc4 * 4u + 0u],
        bias[oc4 * 4u + 1u],
        bias[oc4 * 4u + 2u],
        bias[oc4 * 4u + 3u]);
    uint quad_stride = total_in_channels / 4u;
    uint weight_row0 = oc4 * 4u * quad_stride;
    uint channel_base = 0;
    [unroll]
    for (uint b = 0; b < 8; ++b) {
        uint channels = branch_channels(b);
        if (b >= input_count || channels == 0) {
            continue;
        }
        uint quads = channels / 4u;
        uint cbase4 = channel_base / 4u;
        uint input_base = (n * channels) * plane + spatial;
        [loop]
        for (uint q = 0; q < quads; ++q) {
            float v0 = read_input(b, input_base + (q * 4u + 0u) * plane);
            float v1 = read_input(b, input_base + (q * 4u + 1u) * plane);
            float v2 = read_input(b, input_base + (q * 4u + 2u) * plane);
            float v3 = read_input(b, input_base + (q * 4u + 3u) * plane);
            float4 w0 = weight4[weight_row0 + cbase4 + q];
            float4 w1 = weight4[weight_row0 + quad_stride + cbase4 + q];
            float4 w2 = weight4[weight_row0 + 2u * quad_stride + cbase4 + q];
            float4 w3 = weight4[weight_row0 + 3u * quad_stride + cbase4 + q];
            acc.x += v0 * w0.x + v1 * w0.y + v2 * w0.z + v3 * w0.w;
            acc.y += v0 * w1.x + v1 * w1.y + v2 * w1.z + v3 * w1.w;
            acc.z += v0 * w2.x + v1 * w2.y + v2 * w2.z + v3 * w2.w;
            acc.w += v0 * w3.x + v1 * w3.y + v2 * w3.z + v3 * w3.w;
        }
        channel_base += channels;
    }
#ifdef AEXRT_SILU
    acc = acc / (1.0 + exp(-acc));
#endif
    uint out_plane = out_h * out_w;
    uint out_base = ((n * out_channels + oc4 * 4u) * out_plane) + y * out_w + x;
    output[out_base + 0u * out_plane] = acc.x;
    output[out_base + 1u * out_plane] = acc.y;
    output[out_base + 2u * out_plane] = acc.z;
    output[out_base + 3u * out_plane] = acc.w;
}
)";
    D3D_SHADER_MACRO silu_macros[] = {
        {"AEXRT_SILU", "1"},
        {nullptr, nullptr},
    };
    ComPtr<ID3DBlob> shader;
    ComPtr<ID3DBlob> errors;
    HRESULT hr = D3DCompile(shader_source, std::strlen(shader_source), "aexrt_concat_conv1x1_vec4_float32", silu ? silu_macros : nullptr, nullptr, "main", "cs_5_0", D3DCOMPILE_OPTIMIZATION_LEVEL3, 0, &shader, &errors);
    if (FAILED(hr)) return hr;

    D3D12_COMPUTE_PIPELINE_STATE_DESC pso{};
    pso.pRootSignature = ctx->concat_conv_root_signature.Get();
    pso.CS.pShaderBytecode = shader->GetBufferPointer();
    pso.CS.BytecodeLength = shader->GetBufferSize();
    return aexrt_create_compute_pipeline_state(ctx, &pso, IID_PPV_ARGS(&target));
}

/* gemm256：分块协作 GEMM。16x16 输出 tile（oc x pixel），K 每轮 32 通道，
 * A/B tile 经 groupshared 分块（padding 消 bank conflict），staging 阶段
 * 全 warp 连续地址 coalesced。针对 @10x10/@20x20 小空间大通道形状：
 * 旧 per-thread 串行 K 循环只有几千线程且依赖链长，延迟完全打不满；
 * 这里把 K 维做成组内协作，线程数与 MLP 同时提升。 */
static HRESULT ensure_concat_conv1x1_gemm256_pipeline(AexrtDevice* ctx, bool silu) {
    ComPtr<ID3D12PipelineState>& target = silu ? ctx->concat_conv1x1_gemm256_silu_pso : ctx->concat_conv1x1_gemm256_linear_pso;
    if (ctx->concat_conv_root_signature && target) {
        return S_OK;
    }
    if (!ctx->concat_conv_root_signature) {
        HRESULT hr = ensure_concat_conv1x1_pipeline(ctx, silu);
        if (FAILED(hr)) return hr;
    }
    const char* shader_source = R"(
StructuredBuffer<float> input0 : register(t0);
StructuredBuffer<float> input1 : register(t1);
StructuredBuffer<float> input2 : register(t2);
StructuredBuffer<float> input3 : register(t3);
StructuredBuffer<float> input4 : register(t4);
StructuredBuffer<float> input5 : register(t5);
StructuredBuffer<float> input6 : register(t6);
StructuredBuffer<float> input7 : register(t7);
StructuredBuffer<float> weight : register(t8);
StructuredBuffer<float> bias : register(t9);
RWStructuredBuffer<float> output : register(u0);
cbuffer AexrtConcatConvConstants : register(b0) {
    uint batch;
    uint total_in_channels;
    uint height;
    uint width;
    uint out_channels;
    uint out_h;
    uint out_w;
    uint input_count;
    uint c0;
    uint c1;
    uint c2;
    uint c3;
    uint c4;
    uint c5;
    uint c6;
    uint c7;
};
groupshared float tile_a[16][33];
groupshared float tile_b[32][17];
float read_input(uint branch, uint idx) {
    if (branch == 0) return input0[idx];
    if (branch == 1) return input1[idx];
    if (branch == 2) return input2[idx];
    if (branch == 3) return input3[idx];
    if (branch == 4) return input4[idx];
    if (branch == 5) return input5[idx];
    if (branch == 6) return input6[idx];
    return input7[idx];
}
uint branch_channels(uint branch) {
    if (branch == 0) return c0;
    if (branch == 1) return c1;
    if (branch == 2) return c2;
    if (branch == 3) return c3;
    if (branch == 4) return c4;
    if (branch == 5) return c5;
    if (branch == 6) return c6;
    return c7;
}
[numthreads(16, 16, 1)]
void main(uint3 group_id : SV_GroupID, uint3 group_tid : SV_GroupThreadID) {
    uint plane = height * width;
    uint n0 = group_id.x * 16u;
    uint oc0 = group_id.y * 16u;
    uint n_batch = group_id.z;
    uint m = group_tid.y;
    uint n = group_tid.x;
    uint oc = oc0 + m;
    uint pixel = n0 + n;
    bool m_ok = oc < out_channels;
    bool n_ok = pixel < plane;
    float acc = m_ok ? bias[oc] : 0.0;
    uint channel_base = 0;
    [unroll]
    for (uint b = 0; b < 8; ++b) {
        uint channels = branch_channels(b);
        if (b >= input_count || channels == 0) {
            continue;
        }
        uint weight_row = m_ok ? oc * total_in_channels + channel_base : 0u;
        [loop]
        for (uint k0 = 0u; k0 < channels; k0 += 32u) {
            /* staging：256 线程各装 2 个 A 元素 + 2 个 B 元素，行内连续。 */
            uint l = group_tid.y * 16u + group_tid.x;
            [unroll]
            for (uint s = 0; s < 2; ++s) {
                uint a_idx = l + s * 256u;
                uint a_m = a_idx / 32u;
                uint a_k = a_idx - a_m * 32u;
                uint gk = k0 + a_k;
                bool gk_ok = gk < channels;
                tile_a[a_m][a_k] = (gk_ok && (oc0 + a_m) < out_channels)
                    ? weight[(oc0 + a_m) * total_in_channels + channel_base + gk]
                    : 0.0;
                uint b_idx = a_idx;
                uint b_k = b_idx / 16u;
                uint b_n = b_idx - b_k * 16u;
                uint gbk = k0 + b_k;
                uint gp = n0 + b_n;
                tile_b[b_k][b_n] = (gbk < channels && gp < plane)
                    ? read_input(b, (n_batch * channels + gbk) * plane + gp)
                    : 0.0;
            }
            GroupMemoryBarrierWithGroupSync();
            [unroll]
            for (uint kk = 0; kk < 32; ++kk) {
                acc += tile_a[m][kk] * tile_b[kk][n];
            }
            GroupMemoryBarrierWithGroupSync();
        }
        channel_base += channels;
    }
    if (m_ok && n_ok) {
#ifdef AEXRT_SILU
        acc = acc / (1.0 + exp(-acc));
#endif
        output[(n_batch * out_channels + oc) * plane + pixel] = acc;
    }
}
)";
    D3D_SHADER_MACRO silu_macros[] = {
        {"AEXRT_SILU", "1"},
        {nullptr, nullptr},
    };
    ComPtr<ID3DBlob> shader;
    ComPtr<ID3DBlob> errors;
    HRESULT hr = D3DCompile(shader_source, std::strlen(shader_source), "aexrt_concat_conv1x1_gemm256_float32", silu ? silu_macros : nullptr, nullptr, "main", "cs_5_0", D3DCOMPILE_OPTIMIZATION_LEVEL3, 0, &shader, &errors);
    if (FAILED(hr)) return hr;

    D3D12_COMPUTE_PIPELINE_STATE_DESC pso{};
    pso.pRootSignature = ctx->concat_conv_root_signature.Get();
    pso.CS.pShaderBytecode = shader->GetBufferPointer();
    pso.CS.BytecodeLength = shader->GetBufferSize();
    return aexrt_create_compute_pipeline_state(ctx, &pso, IID_PPV_ARGS(&target));
}

static HRESULT ensure_concat_conv1x1_gemm_pipeline(AexrtDevice* ctx, bool silu) {
    if (!ctx) return E_INVALIDARG;
    ComPtr<ID3D12PipelineState>& target = silu ? ctx->concat_conv1x1_gemm_silu_pso : ctx->concat_conv1x1_gemm_linear_pso;
    if (ctx->concat_conv_root_signature && target) return S_OK;
    const char* shader_source = R"(
StructuredBuffer<float> input0 : register(t0);
StructuredBuffer<float> input1 : register(t1);
StructuredBuffer<float> input2 : register(t2);
StructuredBuffer<float> input3 : register(t3);
StructuredBuffer<float> input4 : register(t4);
StructuredBuffer<float> input5 : register(t5);
StructuredBuffer<float> input6 : register(t6);
StructuredBuffer<float> input7 : register(t7);
StructuredBuffer<float> weight : register(t8);
StructuredBuffer<float> bias : register(t9);
RWStructuredBuffer<float> output : register(u0);
cbuffer AexrtConcatConvConstants : register(b0) {
    uint batch;
    uint total_in_channels;
    uint height;
    uint width;
    uint out_channels;
    uint out_h;
    uint out_w;
    uint input_count;
    uint c0;
    uint c1;
    uint c2;
    uint c3;
    uint c4;
    uint c5;
    uint c6;
    uint c7;
};
#define AEXRT_M_TILE 8u
#define AEXRT_N_TILE 32u
#define AEXRT_K_TILE 32u
groupshared float w_tile[AEXRT_M_TILE * AEXRT_K_TILE];
groupshared float x_tile[AEXRT_K_TILE * AEXRT_N_TILE];

uint branch_channels(uint branch) {
    if (branch == 0u) return c0;
    if (branch == 1u) return c1;
    if (branch == 2u) return c2;
    if (branch == 3u) return c3;
    if (branch == 4u) return c4;
    if (branch == 5u) return c5;
    if (branch == 6u) return c6;
    return c7;
}

float read_branch(uint branch, uint idx) {
    if (branch == 0u) return input0[idx];
    if (branch == 1u) return input1[idx];
    if (branch == 2u) return input2[idx];
    if (branch == 3u) return input3[idx];
    if (branch == 4u) return input4[idx];
    if (branch == 5u) return input5[idx];
    if (branch == 6u) return input6[idx];
    return input7[idx];
}

void map_channel(uint channel, out uint branch, out uint local_channel, out uint channels) {
    uint base = 0u;
    [unroll]
    for (uint b = 0u; b < 8u; ++b) {
        uint ch = branch_channels(b);
        if (b < input_count && channel < base + ch) {
            branch = b;
            local_channel = channel - base;
            channels = ch;
            return;
        }
        base += ch;
    }
    branch = 7u;
    local_channel = 0u;
    channels = max(c7, 1u);
}

[numthreads(AEXRT_M_TILE, AEXRT_N_TILE, 1)]
void main(uint3 group_id : SV_GroupID, uint3 group_tid : SV_GroupThreadID) {
    uint local_m = group_tid.x;
    uint local_n = group_tid.y;
    uint linear_tid = local_n * AEXRT_M_TILE + local_m;
    uint oc = group_id.y * AEXRT_M_TILE + local_m;
    uint n_index = group_id.x * AEXRT_N_TILE + local_n;
    uint spatial_size = height * width;
    uint total_n = batch * spatial_size;
    uint batch_id = n_index / spatial_size;
    uint pos = n_index - batch_id * spatial_size;
    float acc = oc < out_channels ? bias[oc] : 0.0;

    for (uint k_base = 0u; k_base < total_in_channels; k_base += AEXRT_K_TILE) {
        for (uint e = linear_tid; e < AEXRT_M_TILE * AEXRT_K_TILE; e += AEXRT_M_TILE * AEXRT_N_TILE) {
            uint wm = e / AEXRT_K_TILE;
            uint wk = e - wm * AEXRT_K_TILE;
            uint load_oc = group_id.y * AEXRT_M_TILE + wm;
            uint kg = k_base + wk;
            float wv = 0.0;
            if (load_oc < out_channels && kg < total_in_channels) {
                wv = weight[load_oc * total_in_channels + kg];
            }
            w_tile[e] = wv;
        }
        for (uint xe = linear_tid; xe < AEXRT_K_TILE * AEXRT_N_TILE; xe += AEXRT_M_TILE * AEXRT_N_TILE) {
            uint xk = xe / AEXRT_N_TILE;
            uint xn = xe - xk * AEXRT_N_TILE;
            uint load_n = group_id.x * AEXRT_N_TILE + xn;
            uint kg2 = k_base + xk;
            float xv = 0.0;
            if (load_n < total_n && kg2 < total_in_channels) {
                uint load_batch = load_n / spatial_size;
                uint load_pos = load_n - load_batch * spatial_size;
                uint branch = 0u;
                uint local_channel = 0u;
                uint channels = 0u;
                map_channel(kg2, branch, local_channel, channels);
                uint input_idx = (load_batch * channels + local_channel) * spatial_size + load_pos;
                xv = read_branch(branch, input_idx);
            }
            x_tile[xe] = xv;
        }
        GroupMemoryBarrierWithGroupSync();
        if (oc < out_channels && n_index < total_n) {
            [unroll]
            for (uint kk = 0u; kk < AEXRT_K_TILE; ++kk) {
                if (k_base + kk < total_in_channels) {
                    acc += w_tile[local_m * AEXRT_K_TILE + kk] * x_tile[kk * AEXRT_N_TILE + local_n];
                }
            }
        }
        GroupMemoryBarrierWithGroupSync();
    }
    if (oc < out_channels && n_index < total_n) {
        uint out_idx = ((batch_id * out_channels + oc) * spatial_size) + pos;
#ifdef AEXRT_SILU
        acc = acc / (1.0 + exp(-acc));
#endif
        output[out_idx] = acc;
    }
}
)";
    D3D_SHADER_MACRO silu_macros[] = {
        {"AEXRT_SILU", "1"},
        {nullptr, nullptr},
    };
    ComPtr<ID3DBlob> shader;
    ComPtr<ID3DBlob> errors;
    HRESULT hr = D3DCompile(shader_source, std::strlen(shader_source), "aexrt_concat_conv1x1_gemm_float32", silu ? silu_macros : nullptr, nullptr, "main", "cs_5_0", D3DCOMPILE_OPTIMIZATION_LEVEL3, 0, &shader, &errors);
    if (FAILED(hr)) return hr;

    if (!ctx->concat_conv_root_signature) {
        D3D12_DESCRIPTOR_RANGE srv_range{};
        srv_range.RangeType = D3D12_DESCRIPTOR_RANGE_TYPE_SRV;
        srv_range.NumDescriptors = 10;
        srv_range.BaseShaderRegister = 0;
        srv_range.OffsetInDescriptorsFromTableStart = D3D12_DESCRIPTOR_RANGE_OFFSET_APPEND;
        D3D12_DESCRIPTOR_RANGE uav_range{};
        uav_range.RangeType = D3D12_DESCRIPTOR_RANGE_TYPE_UAV;
        uav_range.NumDescriptors = 1;
        uav_range.BaseShaderRegister = 0;
        uav_range.OffsetInDescriptorsFromTableStart = D3D12_DESCRIPTOR_RANGE_OFFSET_APPEND;

        D3D12_ROOT_PARAMETER params[3]{};
        params[0].ParameterType = D3D12_ROOT_PARAMETER_TYPE_DESCRIPTOR_TABLE;
        params[0].DescriptorTable.NumDescriptorRanges = 1;
        params[0].DescriptorTable.pDescriptorRanges = &srv_range;
        params[1].ParameterType = D3D12_ROOT_PARAMETER_TYPE_DESCRIPTOR_TABLE;
        params[1].DescriptorTable.NumDescriptorRanges = 1;
        params[1].DescriptorTable.pDescriptorRanges = &uav_range;
        params[2].ParameterType = D3D12_ROOT_PARAMETER_TYPE_32BIT_CONSTANTS;
        params[2].Constants.ShaderRegister = 0;
        params[2].Constants.Num32BitValues = 16;

        D3D12_ROOT_SIGNATURE_DESC root_desc{};
        root_desc.NumParameters = 3;
        root_desc.pParameters = params;
        ComPtr<ID3DBlob> root_blob;
        hr = D3D12SerializeRootSignature(&root_desc, D3D_ROOT_SIGNATURE_VERSION_1, &root_blob, &errors);
        if (FAILED(hr)) return hr;
        hr = ctx->device->CreateRootSignature(0, root_blob->GetBufferPointer(), root_blob->GetBufferSize(), IID_PPV_ARGS(&ctx->concat_conv_root_signature));
        if (FAILED(hr)) return hr;
    }

    D3D12_COMPUTE_PIPELINE_STATE_DESC pso{};
    pso.pRootSignature = ctx->concat_conv_root_signature.Get();
    pso.CS.pShaderBytecode = shader->GetBufferPointer();
    pso.CS.BytecodeLength = shader->GetBufferSize();
    return aexrt_create_compute_pipeline_state(ctx, &pso, IID_PPV_ARGS(&target));
}

static bool should_use_concat_conv1x1_direct_pack4(
    uint32_t total_in_channels,
    uint32_t out_channels,
    uint32_t height,
    uint32_t width) {
    if (aexrt_env_flag("AEXRT_NATIVE_D3D12_DISABLE_CONCAT_CONV1X1_DIRECT_PACK4")) return false;
    return total_in_channels >= 64 &&
        out_channels >= 64 &&
        (out_channels % 4) == 0 &&
        uint64_t(height) * width >= 100;
}

static HRESULT ensure_concat_conv1x1_direct_pack4_pipeline(AexrtDevice* ctx, bool silu) {
    if (!ctx) return E_INVALIDARG;
    ComPtr<ID3D12PipelineState>& target = silu ? ctx->concat_conv1x1_direct_pack4_silu_pso : ctx->concat_conv1x1_direct_pack4_linear_pso;
    if (ctx->concat_conv_root_signature && target) return S_OK;
    const char* shader_source = R"(
Buffer<float> input0 : register(t0);
Buffer<float> input1 : register(t1);
Buffer<float> input2 : register(t2);
Buffer<float> input3 : register(t3);
Buffer<float> input4 : register(t4);
Buffer<float> input5 : register(t5);
Buffer<float> input6 : register(t6);
Buffer<float> input7 : register(t7);
StructuredBuffer<float> weight : register(t8);
StructuredBuffer<float> bias : register(t9);
RWBuffer<float> output : register(u0);
cbuffer AexrtConcatConvConstants : register(b0) {
    uint batch;
    uint total_in_channels;
    uint height;
    uint width;
    uint out_channels;
    uint out_h;
    uint out_w;
    uint input_count;
    uint c0;
    uint c1;
    uint c2;
    uint c3;
    uint c4;
    uint c5;
    uint c6;
    uint c7;
};
float read_input(uint branch, uint idx) {
    if (branch == 0u) return input0[idx];
    if (branch == 1u) return input1[idx];
    if (branch == 2u) return input2[idx];
    if (branch == 3u) return input3[idx];
    if (branch == 4u) return input4[idx];
    if (branch == 5u) return input5[idx];
    if (branch == 6u) return input6[idx];
    return input7[idx];
}
uint branch_channels(uint branch) {
    if (branch == 0u) return c0;
    if (branch == 1u) return c1;
    if (branch == 2u) return c2;
    if (branch == 3u) return c3;
    if (branch == 4u) return c4;
    if (branch == 5u) return c5;
    if (branch == 6u) return c6;
    return c7;
}
[numthreads(128, 1, 1)]
void main(uint3 tid : SV_DispatchThreadID) {
    uint idx = tid.x;
    uint spatial = height * width;
    uint oc_groups = (out_channels + 3u) / 4u;
    uint total = batch * oc_groups * spatial;
    if (idx >= total) return;

    uint pos = idx % spatial;
    uint t = idx / spatial;
    uint oc_group = t % oc_groups;
    uint n = t / oc_groups;
    uint oc0 = oc_group * 4u;
    uint oc1 = oc0 + 1u;
    uint oc2 = oc0 + 2u;
    uint oc3 = oc0 + 3u;
    float acc0 = bias[oc0];
    float acc1 = oc1 < out_channels ? bias[oc1] : 0.0;
    float acc2 = oc2 < out_channels ? bias[oc2] : 0.0;
    float acc3 = oc3 < out_channels ? bias[oc3] : 0.0;

    uint channel_base = 0u;
    [unroll]
    for (uint b = 0u; b < 8u; ++b) {
        uint channels = branch_channels(b);
        if (b >= input_count || channels == 0u) {
            continue;
        }
        for (uint c = 0u; c < channels; ++c) {
            uint input_idx = (n * channels + c) * spatial + pos;
            float v = read_input(b, input_idx);
            uint k = channel_base + c;
            acc0 += v * weight[oc0 * total_in_channels + k];
            if (oc1 < out_channels) acc1 += v * weight[oc1 * total_in_channels + k];
            if (oc2 < out_channels) acc2 += v * weight[oc2 * total_in_channels + k];
            if (oc3 < out_channels) acc3 += v * weight[oc3 * total_in_channels + k];
        }
        channel_base += channels;
    }

    if (oc0 < out_channels) {
        uint out_idx0 = ((n * out_channels + oc0) * spatial) + pos;
#ifdef AEXRT_SILU
        acc0 = acc0 / (1.0 + exp(-acc0));
#endif
        output[out_idx0] = acc0;
    }
    if (oc1 < out_channels) {
        uint out_idx1 = ((n * out_channels + oc1) * spatial) + pos;
#ifdef AEXRT_SILU
        acc1 = acc1 / (1.0 + exp(-acc1));
#endif
        output[out_idx1] = acc1;
    }
    if (oc2 < out_channels) {
        uint out_idx2 = ((n * out_channels + oc2) * spatial) + pos;
#ifdef AEXRT_SILU
        acc2 = acc2 / (1.0 + exp(-acc2));
#endif
        output[out_idx2] = acc2;
    }
    if (oc3 < out_channels) {
        uint out_idx3 = ((n * out_channels + oc3) * spatial) + pos;
#ifdef AEXRT_SILU
        acc3 = acc3 / (1.0 + exp(-acc3));
#endif
        output[out_idx3] = acc3;
    }
}
)";
    D3D_SHADER_MACRO silu_macros[] = {
        {"AEXRT_SILU", "1"},
        {nullptr, nullptr},
    };
    ComPtr<ID3DBlob> shader;
    ComPtr<ID3DBlob> errors;
    HRESULT hr = D3DCompile(shader_source, std::strlen(shader_source), "aexrt_concat_conv1x1_direct_pack4_float32", silu ? silu_macros : nullptr, nullptr, "main", "cs_5_0", D3DCOMPILE_OPTIMIZATION_LEVEL3, 0, &shader, &errors);
    if (FAILED(hr)) return hr;

    if (!ctx->concat_conv_root_signature) {
        D3D12_DESCRIPTOR_RANGE srv_range{};
        srv_range.RangeType = D3D12_DESCRIPTOR_RANGE_TYPE_SRV;
        srv_range.NumDescriptors = 10;
        srv_range.BaseShaderRegister = 0;
        srv_range.OffsetInDescriptorsFromTableStart = D3D12_DESCRIPTOR_RANGE_OFFSET_APPEND;
        D3D12_DESCRIPTOR_RANGE uav_range{};
        uav_range.RangeType = D3D12_DESCRIPTOR_RANGE_TYPE_UAV;
        uav_range.NumDescriptors = 1;
        uav_range.BaseShaderRegister = 0;
        uav_range.OffsetInDescriptorsFromTableStart = D3D12_DESCRIPTOR_RANGE_OFFSET_APPEND;

        D3D12_ROOT_PARAMETER params[3]{};
        params[0].ParameterType = D3D12_ROOT_PARAMETER_TYPE_DESCRIPTOR_TABLE;
        params[0].DescriptorTable.NumDescriptorRanges = 1;
        params[0].DescriptorTable.pDescriptorRanges = &srv_range;
        params[1].ParameterType = D3D12_ROOT_PARAMETER_TYPE_DESCRIPTOR_TABLE;
        params[1].DescriptorTable.NumDescriptorRanges = 1;
        params[1].DescriptorTable.pDescriptorRanges = &uav_range;
        params[2].ParameterType = D3D12_ROOT_PARAMETER_TYPE_32BIT_CONSTANTS;
        params[2].Constants.ShaderRegister = 0;
        params[2].Constants.Num32BitValues = 16;

        D3D12_ROOT_SIGNATURE_DESC root_desc{};
        root_desc.NumParameters = 3;
        root_desc.pParameters = params;
        ComPtr<ID3DBlob> root_blob;
        hr = D3D12SerializeRootSignature(&root_desc, D3D_ROOT_SIGNATURE_VERSION_1, &root_blob, &errors);
        if (FAILED(hr)) return hr;
        hr = ctx->device->CreateRootSignature(0, root_blob->GetBufferPointer(), root_blob->GetBufferSize(), IID_PPV_ARGS(&ctx->concat_conv_root_signature));
        if (FAILED(hr)) return hr;
    }

    D3D12_COMPUTE_PIPELINE_STATE_DESC pso{};
    pso.pRootSignature = ctx->concat_conv_root_signature.Get();
    pso.CS.pShaderBytecode = shader->GetBufferPointer();
    pso.CS.BytecodeLength = shader->GetBufferSize();
    return aexrt_create_compute_pipeline_state(ctx, &pso, IID_PPV_ARGS(&target));
}

static bool should_use_concat_conv1x1_tileflow_40x40_512x128(
    uint32_t batch,
    uint32_t input_count,
    const std::vector<uint32_t>& channels,
    uint32_t total_in_channels,
    uint32_t out_channels,
    uint32_t height,
    uint32_t width,
    uint32_t activation) {
    if (aexrt_env_flag("AEXRT_NATIVE_D3D12_DISABLE_TILEFLOW_CONCAT_40X40_512X128")) return false;
    return batch == 1 && input_count == 2 && channels.size() == 2 &&
        channels[0] == 256 && channels[1] == 256 &&
        total_in_channels == 512 && out_channels == 128 &&
        height == 40 && width == 40 && activation == 1;
}

static HRESULT ensure_concat_conv1x1_native_fp16_oc8_pos2_pipeline(AexrtDevice* ctx, bool silu) {
    if (!ctx || !ctx->native_fp16_supported || !ctx->dxc_available ||
        ctx->highest_shader_model < D3D_SHADER_MODEL_6_2) return E_NOINTERFACE;
    ComPtr<ID3D12PipelineState>& target = silu
        ? ctx->concat_conv1x1_native_fp16_oc8_pos2_silu_pso
        : ctx->concat_conv1x1_native_fp16_oc8_pos2_linear_pso;
    if (ctx->concat_conv_root_signature && target) return S_OK;
    if (!ctx->concat_conv_root_signature) {
        HRESULT root_hr = ensure_concat_conv1x1_pipeline(ctx, silu);
        if (FAILED(root_hr)) return root_hr;
    }
    const char* shader_source = R"(
Buffer<float> input0 : register(t0);
Buffer<float> input1 : register(t1);
Buffer<float> input2 : register(t2);
Buffer<float> input3 : register(t3);
Buffer<float> input4 : register(t4);
Buffer<float> input5 : register(t5);
Buffer<float> input6 : register(t6);
Buffer<float> input7 : register(t7);
StructuredBuffer<uint2> weight : register(t8);
StructuredBuffer<float> bias : register(t9);
RWBuffer<float> output : register(u0);
cbuffer AexrtConcatConvConstants : register(b0) {
    uint batch; uint total_in_channels; uint height; uint width;
    uint out_channels; uint out_h; uint out_w; uint input_count;
    uint c0; uint c1; uint c2; uint c3; uint c4; uint c5; uint c6; uint c7;
};

float16_t4 load_half4(uint2 packed) {
    return float16_t4(
        (float16_t)f16tof32(packed.x),
        (float16_t)f16tof32(packed.x >> 16u),
        (float16_t)f16tof32(packed.y),
        (float16_t)f16tof32(packed.y >> 16u));
}
uint branch_channels(uint source) {
    if (source == 0u) return c0;
    if (source == 1u) return c1;
    if (source == 2u) return c2;
    if (source == 3u) return c3;
    if (source == 4u) return c4;
    if (source == 5u) return c5;
    if (source == 6u) return c6;
    return c7;
}
float read_branch(uint source, uint idx) {
    if (source == 0u) return input0[idx];
    if (source == 1u) return input1[idx];
    if (source == 2u) return input2[idx];
    if (source == 3u) return input3[idx];
    if (source == 4u) return input4[idx];
    if (source == 5u) return input5[idx];
    if (source == 6u) return input6[idx];
    return input7[idx];
}
float read_concat(uint global_c, uint n, uint pos) {
    uint channel_base = 0u;
    [unroll]
    for (uint source = 0u; source < 8u; ++source) {
        uint channels = source < input_count ? branch_channels(source) : 0u;
        if (global_c < channel_base + channels) {
            uint local_c = global_c - channel_base;
            return read_branch(source, (n * channels + local_c) * height * width + pos);
        }
        channel_base += channels;
    }
    return 0.0;
}

[numthreads(128, 1, 1)]
void main(uint3 tid : SV_DispatchThreadID) {
    uint spatial = height * width;
    uint pair_count = (spatial + 1u) / 2u;
    uint oc_groups = out_channels / 8u;
    uint idx = tid.x;
    uint total = batch * oc_groups * pair_count;
    if (idx >= total) return;
    uint pair = idx % pair_count;
    uint t = idx / pair_count;
    uint oc_group = t % oc_groups;
    uint n = t / oc_groups;
    uint pos0 = pair * 2u;
    uint pos1 = pos0 + 1u;
    bool valid1 = pos1 < spatial;
    uint oc0 = oc_group * 8u;
    float4 acc0_lo = float4(bias[oc0], bias[oc0 + 1u], bias[oc0 + 2u], bias[oc0 + 3u]);
    float4 acc0_hi = float4(bias[oc0 + 4u], bias[oc0 + 5u], bias[oc0 + 6u], bias[oc0 + 7u]);
    float4 acc1_lo = acc0_lo;
    float4 acc1_hi = acc0_hi;
    uint global_c = 0u;
    [unroll]
    for (uint source = 0u; source < 8u; ++source) {
        uint channels = source < input_count ? branch_channels(source) : 0u;
        [loop]
        for (uint c_base = 0u; c_base < channels; c_base += 4u) {
            float16_t4 partial0_lo = float16_t4(0.0, 0.0, 0.0, 0.0);
            float16_t4 partial0_hi = float16_t4(0.0, 0.0, 0.0, 0.0);
            float16_t4 partial1_lo = float16_t4(0.0, 0.0, 0.0, 0.0);
            float16_t4 partial1_hi = float16_t4(0.0, 0.0, 0.0, 0.0);
            [unroll]
            for (uint lane = 0u; lane < 4u; ++lane) {
                uint c = c_base + lane;
                if (c < channels) {
                    uint input_base = (n * channels + c) * spatial;
                    float16_t x0 = (float16_t)read_branch(source, input_base + pos0);
                    float16_t x1 = valid1
                        ? (float16_t)read_branch(source, input_base + pos1)
                        : (float16_t)0.0;
                    uint ic = global_c + c;
                    uint weight_base = (oc_group * total_in_channels + ic) * 2u;
                    float16_t4 w_lo = load_half4(weight[weight_base]);
                    float16_t4 w_hi = load_half4(weight[weight_base + 1u]);
                    partial0_lo += x0 * w_lo;
                    partial0_hi += x0 * w_hi;
                    partial1_lo += x1 * w_lo;
                    partial1_hi += x1 * w_hi;
                }
            }
            acc0_lo += float4(partial0_lo);
            acc0_hi += float4(partial0_hi);
            acc1_lo += float4(partial1_lo);
            acc1_hi += float4(partial1_hi);
        }
        global_c += channels;
    }
#ifdef AEXRT_SILU
    acc0_lo *= 1.0 / (1.0 + exp(-acc0_lo));
    acc0_hi *= 1.0 / (1.0 + exp(-acc0_hi));
    acc1_lo *= 1.0 / (1.0 + exp(-acc1_lo));
    acc1_hi *= 1.0 / (1.0 + exp(-acc1_hi));
#endif
    uint output_base = (n * out_channels + oc0) * spatial;
    output[output_base + pos0] = acc0_lo.x;
    output[output_base + spatial + pos0] = acc0_lo.y;
    output[output_base + spatial * 2u + pos0] = acc0_lo.z;
    output[output_base + spatial * 3u + pos0] = acc0_lo.w;
    output[output_base + spatial * 4u + pos0] = acc0_hi.x;
    output[output_base + spatial * 5u + pos0] = acc0_hi.y;
    output[output_base + spatial * 6u + pos0] = acc0_hi.z;
    output[output_base + spatial * 7u + pos0] = acc0_hi.w;
    if (valid1) {
        output[output_base + pos1] = acc1_lo.x;
        output[output_base + spatial + pos1] = acc1_lo.y;
        output[output_base + spatial * 2u + pos1] = acc1_lo.z;
        output[output_base + spatial * 3u + pos1] = acc1_lo.w;
        output[output_base + spatial * 4u + pos1] = acc1_hi.x;
        output[output_base + spatial * 5u + pos1] = acc1_hi.y;
        output[output_base + spatial * 6u + pos1] = acc1_hi.z;
        output[output_base + spatial * 7u + pos1] = acc1_hi.w;
    }
}
)";
    D3D_SHADER_MACRO silu_macros[] = {
        {"AEXRT_SILU", "1"},
        {nullptr, nullptr},
    };
    const D3D_SHADER_MACRO* macros = silu ? silu_macros : nullptr;
    ComPtr<ID3DBlob> shader;
    ComPtr<ID3DBlob> errors;
    HRESULT hr = g_aexrt_engine_compile_model && g_aexrt_engine_use_dxil
        ? aexrt_engine_d3d_compile(
            shader_source,
            std::strlen(shader_source),
            silu ? "aexrt_concat_conv1x1_silu_native_fp16_oc8_pos2" : "aexrt_concat_conv1x1_linear_native_fp16_oc8_pos2",
            macros,
            nullptr,
            "main",
            "cs_6_2",
            D3DCOMPILE_OPTIMIZATION_LEVEL3,
            0,
            &shader,
            &errors)
        : aexrt_compile_dxil(shader_source, std::strlen(shader_source), macros, "main", &shader, &errors);
    if (FAILED(hr)) return hr;
    D3D12_COMPUTE_PIPELINE_STATE_DESC pso{};
    pso.pRootSignature = ctx->concat_conv_root_signature.Get();
    pso.CS.pShaderBytecode = shader->GetBufferPointer();
    pso.CS.BytecodeLength = shader->GetBufferSize();
    target.Reset();
    return aexrt_create_compute_pipeline_state(ctx, &pso, IID_PPV_ARGS(&target));
}

static HRESULT ensure_concat_conv1x1_tileflow_40x40_512x128_pipeline(AexrtDevice* ctx) {
    if (!ctx) return E_INVALIDARG;
    if (ctx->concat_conv_root_signature && ctx->concat_conv1x1_tileflow_40x40_512x128_silu_pso) return S_OK;
    if (!ctx->concat_conv_root_signature) {
        HRESULT hr = ensure_concat_conv1x1_direct_pack4_pipeline(ctx, true);
        if (FAILED(hr)) return hr;
    }
    const char* shader_source = R"(
#define AEXRT_SPATIAL 1600u
#define AEXRT_IN_CHANNELS 512u
#define AEXRT_BRANCH_CHANNELS 256u
#define AEXRT_OUT_CHANNELS 128u
StructuredBuffer<float> input0 : register(t0);
StructuredBuffer<float> input1 : register(t1);
StructuredBuffer<float> weight : register(t8);
StructuredBuffer<float> bias : register(t9);
RWStructuredBuffer<float> output : register(u0);

[numthreads(128, 1, 1)]
void main(uint3 dispatch_id : SV_DispatchThreadID) {
    uint idx = dispatch_id.x;
    uint spatial_pairs = AEXRT_SPATIAL / 2u;
    uint oc_groups = AEXRT_OUT_CHANNELS / 4u;
    uint total = oc_groups * spatial_pairs;
    if (idx >= total) return;

    uint pair = idx % spatial_pairs;
    uint oc_group = idx / spatial_pairs;
    uint pos0 = pair * 2u;
    uint pos1 = pos0 + 1u;
    uint oc0 = oc_group * 4u;
    float4 acc0 = float4(bias[oc0], bias[oc0 + 1u], bias[oc0 + 2u], bias[oc0 + 3u]);
    float4 acc1 = acc0;

    [loop]
    for (uint c0 = 0u; c0 < AEXRT_BRANCH_CHANNELS; ++c0) {
        float4 w = float4(
            weight[(oc0 + 0u) * AEXRT_IN_CHANNELS + c0],
            weight[(oc0 + 1u) * AEXRT_IN_CHANNELS + c0],
            weight[(oc0 + 2u) * AEXRT_IN_CHANNELS + c0],
            weight[(oc0 + 3u) * AEXRT_IN_CHANNELS + c0]);
        acc0 += input0[c0 * AEXRT_SPATIAL + pos0] * w;
        acc1 += input0[c0 * AEXRT_SPATIAL + pos1] * w;
    }
    [loop]
    for (uint c1 = 0u; c1 < AEXRT_BRANCH_CHANNELS; ++c1) {
        uint k = AEXRT_BRANCH_CHANNELS + c1;
        float4 w = float4(
            weight[(oc0 + 0u) * AEXRT_IN_CHANNELS + k],
            weight[(oc0 + 1u) * AEXRT_IN_CHANNELS + k],
            weight[(oc0 + 2u) * AEXRT_IN_CHANNELS + k],
            weight[(oc0 + 3u) * AEXRT_IN_CHANNELS + k]);
        acc0 += input1[c1 * AEXRT_SPATIAL + pos0] * w;
        acc1 += input1[c1 * AEXRT_SPATIAL + pos1] * w;
    }

    acc0 *= 1.0 / (1.0 + exp(-acc0));
    acc1 *= 1.0 / (1.0 + exp(-acc1));
    output[(oc0 + 0u) * AEXRT_SPATIAL + pos0] = acc0.x;
    output[(oc0 + 1u) * AEXRT_SPATIAL + pos0] = acc0.y;
    output[(oc0 + 2u) * AEXRT_SPATIAL + pos0] = acc0.z;
    output[(oc0 + 3u) * AEXRT_SPATIAL + pos0] = acc0.w;
    output[(oc0 + 0u) * AEXRT_SPATIAL + pos1] = acc1.x;
    output[(oc0 + 1u) * AEXRT_SPATIAL + pos1] = acc1.y;
    output[(oc0 + 2u) * AEXRT_SPATIAL + pos1] = acc1.z;
    output[(oc0 + 3u) * AEXRT_SPATIAL + pos1] = acc1.w;
}
)";
    ComPtr<ID3DBlob> shader;
    ComPtr<ID3DBlob> errors;
    HRESULT hr = D3DCompile(
        shader_source, std::strlen(shader_source),
        "aexrt_concat_conv1x1_tileflow_40x40_512x128_float32",
        nullptr, nullptr, "main", "cs_5_0", D3DCOMPILE_OPTIMIZATION_LEVEL3, 0, &shader, &errors);
    if (FAILED(hr)) return hr;
    D3D12_COMPUTE_PIPELINE_STATE_DESC pso{};
    pso.pRootSignature = ctx->concat_conv_root_signature.Get();
    pso.CS.pShaderBytecode = shader->GetBufferPointer();
    pso.CS.BytecodeLength = shader->GetBufferSize();
    return aexrt_create_compute_pipeline_state(
        ctx,
        &pso,
        IID_PPV_ARGS(ctx->concat_conv1x1_tileflow_40x40_512x128_silu_pso.ReleaseAndGetAddressOf()));
}

static HRESULT create_relu_descriptors(AexrtDevice* ctx, AexrtBuffer* input, AexrtBuffer* output, uint64_t element_count, ID3D12DescriptorHeap** out_heap) {
    D3D12_DESCRIPTOR_HEAP_DESC heap_desc{};
    heap_desc.Type = D3D12_DESCRIPTOR_HEAP_TYPE_CBV_SRV_UAV;
    heap_desc.NumDescriptors = 2;
    heap_desc.Flags = D3D12_DESCRIPTOR_HEAP_FLAG_SHADER_VISIBLE;
    ComPtr<ID3D12DescriptorHeap> heap;
    HRESULT hr = ctx->device->CreateDescriptorHeap(&heap_desc, IID_PPV_ARGS(&heap));
    if (FAILED(hr)) {
        return hr;
    }
    const UINT size = ctx->device->GetDescriptorHandleIncrementSize(D3D12_DESCRIPTOR_HEAP_TYPE_CBV_SRV_UAV);
    D3D12_CPU_DESCRIPTOR_HANDLE srv_cpu = heap->GetCPUDescriptorHandleForHeapStart();
    D3D12_CPU_DESCRIPTOR_HANDLE uav_cpu = srv_cpu;
    uav_cpu.ptr += size;

    D3D12_SHADER_RESOURCE_VIEW_DESC srv{};
    srv.Format = DXGI_FORMAT_UNKNOWN;
    srv.ViewDimension = D3D12_SRV_DIMENSION_BUFFER;
    srv.Shader4ComponentMapping = D3D12_DEFAULT_SHADER_4_COMPONENT_MAPPING;
    srv.Buffer.NumElements = static_cast<UINT>(element_count);
    srv.Buffer.StructureByteStride = sizeof(float);
    srv.Buffer.FirstElement = input->element_offset;
    ctx->device->CreateShaderResourceView(input->resource.Get(), &srv, srv_cpu);

    D3D12_UNORDERED_ACCESS_VIEW_DESC uav{};
    uav.Format = DXGI_FORMAT_UNKNOWN;
    uav.ViewDimension = D3D12_UAV_DIMENSION_BUFFER;
    uav.Buffer.NumElements = static_cast<UINT>(element_count);
    uav.Buffer.StructureByteStride = sizeof(float);
    uav.Buffer.FirstElement = output->element_offset;
    ctx->device->CreateUnorderedAccessView(output->resource.Get(), nullptr, &uav, uav_cpu);

    *out_heap = heap.Detach();
    return S_OK;
}

static HRESULT create_add_descriptors(AexrtDevice* ctx, AexrtBuffer* input0, AexrtBuffer* input1, AexrtBuffer* output, uint64_t element_count, ID3D12DescriptorHeap** out_heap) {
    D3D12_DESCRIPTOR_HEAP_DESC heap_desc{};
    heap_desc.Type = D3D12_DESCRIPTOR_HEAP_TYPE_CBV_SRV_UAV;
    heap_desc.NumDescriptors = 3;
    heap_desc.Flags = D3D12_DESCRIPTOR_HEAP_FLAG_SHADER_VISIBLE;
    ComPtr<ID3D12DescriptorHeap> heap;
    HRESULT hr = ctx->device->CreateDescriptorHeap(&heap_desc, IID_PPV_ARGS(&heap));
    if (FAILED(hr)) return hr;

    const UINT size = ctx->device->GetDescriptorHandleIncrementSize(D3D12_DESCRIPTOR_HEAP_TYPE_CBV_SRV_UAV);
    D3D12_CPU_DESCRIPTOR_HANDLE srv0 = heap->GetCPUDescriptorHandleForHeapStart();
    D3D12_CPU_DESCRIPTOR_HANDLE srv1 = srv0;
    srv1.ptr += size;
    D3D12_CPU_DESCRIPTOR_HANDLE uav = srv1;
    uav.ptr += size;

    D3D12_SHADER_RESOURCE_VIEW_DESC srv{};
    srv.Format = DXGI_FORMAT_UNKNOWN;
    srv.ViewDimension = D3D12_SRV_DIMENSION_BUFFER;
    srv.Shader4ComponentMapping = D3D12_DEFAULT_SHADER_4_COMPONENT_MAPPING;
    srv.Buffer.NumElements = static_cast<UINT>(element_count);
    srv.Buffer.StructureByteStride = sizeof(float);
    srv.Buffer.FirstElement = input0->element_offset;
    ctx->device->CreateShaderResourceView(input0->resource.Get(), &srv, srv0);
    srv.Buffer.FirstElement = input1->element_offset;
    ctx->device->CreateShaderResourceView(input1->resource.Get(), &srv, srv1);

    D3D12_UNORDERED_ACCESS_VIEW_DESC uav_desc{};
    uav_desc.Format = DXGI_FORMAT_UNKNOWN;
    uav_desc.ViewDimension = D3D12_UAV_DIMENSION_BUFFER;
    uav_desc.Buffer.NumElements = static_cast<UINT>(element_count);
    uav_desc.Buffer.StructureByteStride = sizeof(float);
    uav_desc.Buffer.FirstElement = output->element_offset;
    ctx->device->CreateUnorderedAccessView(output->resource.Get(), nullptr, &uav_desc, uav);

    *out_heap = heap.Detach();
    return S_OK;
}

static HRESULT create_fused_descriptors(AexrtDevice* ctx, const std::vector<AexrtBuffer*>& inputs, AexrtBuffer* output, uint64_t element_count, ID3D12DescriptorHeap** out_heap) {
    if (!ctx || inputs.empty() || !output || !out_heap) return E_INVALIDARG;
    D3D12_DESCRIPTOR_HEAP_DESC heap_desc{};
    heap_desc.Type = D3D12_DESCRIPTOR_HEAP_TYPE_CBV_SRV_UAV;
    heap_desc.NumDescriptors = static_cast<UINT>(inputs.size() + 1);
    heap_desc.Flags = D3D12_DESCRIPTOR_HEAP_FLAG_SHADER_VISIBLE;
    ComPtr<ID3D12DescriptorHeap> heap;
    HRESULT hr = ctx->device->CreateDescriptorHeap(&heap_desc, IID_PPV_ARGS(&heap));
    if (FAILED(hr)) return hr;

    const UINT size = ctx->device->GetDescriptorHandleIncrementSize(D3D12_DESCRIPTOR_HEAP_TYPE_CBV_SRV_UAV);
    D3D12_CPU_DESCRIPTOR_HANDLE cursor = heap->GetCPUDescriptorHandleForHeapStart();

    D3D12_SHADER_RESOURCE_VIEW_DESC srv{};
    srv.Format = DXGI_FORMAT_UNKNOWN;
    srv.ViewDimension = D3D12_SRV_DIMENSION_BUFFER;
    srv.Shader4ComponentMapping = D3D12_DEFAULT_SHADER_4_COMPONENT_MAPPING;
    srv.Buffer.NumElements = static_cast<UINT>(element_count);
    srv.Buffer.StructureByteStride = sizeof(float);
    for (auto* input : inputs) {
        if (!input) return E_INVALIDARG;
        srv.Buffer.FirstElement = input->element_offset;
        ctx->device->CreateShaderResourceView(input->resource.Get(), &srv, cursor);
        cursor.ptr += size;
    }

    D3D12_UNORDERED_ACCESS_VIEW_DESC uav{};
    uav.Format = DXGI_FORMAT_UNKNOWN;
    uav.ViewDimension = D3D12_UAV_DIMENSION_BUFFER;
    uav.Buffer.NumElements = static_cast<UINT>(element_count);
    uav.Buffer.StructureByteStride = sizeof(float);
    uav.Buffer.FirstElement = output->element_offset;
    ctx->device->CreateUnorderedAccessView(output->resource.Get(), nullptr, &uav, cursor);

    *out_heap = heap.Detach();
    return S_OK;
}

static HRESULT create_conv_silu_descriptors(AexrtDevice* ctx, AexrtBuffer* input, AexrtBuffer* weight, AexrtBuffer* bias, AexrtBuffer* output, const AexrtConv2DDesc* desc, ID3D12DescriptorHeap** out_heap) {
    if (!ctx || !input || !weight || !bias || !output || !desc || !out_heap) return E_INVALIDARG;
    D3D12_DESCRIPTOR_HEAP_DESC heap_desc{};
    heap_desc.Type = D3D12_DESCRIPTOR_HEAP_TYPE_CBV_SRV_UAV;
    heap_desc.NumDescriptors = 4;
    heap_desc.Flags = D3D12_DESCRIPTOR_HEAP_FLAG_SHADER_VISIBLE;
    ComPtr<ID3D12DescriptorHeap> heap;
    HRESULT hr = ctx->device->CreateDescriptorHeap(&heap_desc, IID_PPV_ARGS(&heap));
    if (FAILED(hr)) return hr;

    const UINT size = ctx->device->GetDescriptorHandleIncrementSize(D3D12_DESCRIPTOR_HEAP_TYPE_CBV_SRV_UAV);
    D3D12_CPU_DESCRIPTOR_HANDLE cursor = heap->GetCPUDescriptorHandleForHeapStart();

    D3D12_SHADER_RESOURCE_VIEW_DESC srv{};
    srv.Format = DXGI_FORMAT_UNKNOWN;
    srv.ViewDimension = D3D12_SRV_DIMENSION_BUFFER;
    srv.Shader4ComponentMapping = D3D12_DEFAULT_SHADER_4_COMPONENT_MAPPING;
    srv.Buffer.StructureByteStride = sizeof(float);

    srv.Buffer.NumElements = desc->batch * desc->in_channels * desc->in_h * desc->in_w;
    srv.Buffer.FirstElement = input->element_offset;
    ctx->device->CreateShaderResourceView(input->resource.Get(), &srv, cursor);
    cursor.ptr += size;

    srv.Buffer.NumElements = desc->out_channels * (desc->in_channels / desc->groups) * desc->kernel_h * desc->kernel_w;
    srv.Buffer.FirstElement = weight->element_offset;
    ctx->device->CreateShaderResourceView(weight->resource.Get(), &srv, cursor);
    cursor.ptr += size;

    srv.Buffer.NumElements = desc->out_channels;
    srv.Buffer.FirstElement = bias->element_offset;
    ctx->device->CreateShaderResourceView(bias->resource.Get(), &srv, cursor);
    cursor.ptr += size;

    D3D12_UNORDERED_ACCESS_VIEW_DESC uav{};
    uav.Format = DXGI_FORMAT_UNKNOWN;
    uav.ViewDimension = D3D12_UAV_DIMENSION_BUFFER;
    uav.Buffer.NumElements = desc->batch * desc->out_channels * desc->out_h * desc->out_w;
    uav.Buffer.StructureByteStride = sizeof(float);
    uav.Buffer.FirstElement = output->element_offset;
    ctx->device->CreateUnorderedAccessView(output->resource.Get(), nullptr, &uav, cursor);

    *out_heap = heap.Detach();
    return S_OK;
}

static HRESULT create_descriptor_heap(AexrtDevice* ctx, UINT descriptor_count, ID3D12DescriptorHeap** out_heap) {
    if (!ctx || descriptor_count == 0 || !out_heap) return E_INVALIDARG;
    D3D12_DESCRIPTOR_HEAP_DESC heap_desc{};
    heap_desc.Type = D3D12_DESCRIPTOR_HEAP_TYPE_CBV_SRV_UAV;
    heap_desc.NumDescriptors = descriptor_count;
    heap_desc.Flags = D3D12_DESCRIPTOR_HEAP_FLAG_SHADER_VISIBLE;
    ComPtr<ID3D12DescriptorHeap> heap;
    HRESULT hr = ctx->device->CreateDescriptorHeap(&heap_desc, IID_PPV_ARGS(&heap));
    if (FAILED(hr)) return hr;
    *out_heap = heap.Detach();
    return S_OK;
}

