        uint out_linear = linear + s * AEXRT_THREAD_COUNT;
        active[s] = out_linear < AEXRT_OUT_TILE * AEXRT_SPATIAL;
        uint local_oc = out_linear / AEXRT_SPATIAL;
        out_pos[s] = out_linear - local_oc * AEXRT_SPATIAL;
        out_oc[s] = oc_base + local_oc;
        acc[s] = active[s] ? bias1[out_oc[s]] : 0.0;
