    if (FAILED(ensure_conv_linear_pipeline(device))) return 0;
    ComPtr<ID3D12DescriptorHeap> heap;
    if (FAILED(create_conv_silu_descriptors(device, input, weight, bias, output, desc, &heap))) return 0;

