            break;
        case AexrtTileFlowConvAlgorithm::ImplicitGemm3x3Stride2_80x80_32x64:
            hr = ensure_conv3x3s2_silu_implicit_gemm_exact_pipeline(device, 80u, 32u, 64u);
            if (FAILED(hr)) {
                algorithm = AexrtTileFlowConvAlgorithm::Generic;
                hr = silu ? ensure_conv_silu_pipeline(device) : ensure_conv_linear_pipeline(device);
            }
            break;
        case AexrtTileFlowConvAlgorithm::ImplicitGemm3x3Stride2_40x40_128x128:
            hr = ensure_conv3x3s2_silu_implicit_gemm_exact_pipeline(device, 40u, 128u, 128u);
            if (FAILED(hr)) {
                algorithm = AexrtTileFlowConvAlgorithm::ImplicitGemm3x3;
                hr = ensure_conv3x3_silu_implicit_gemm_pipeline(device);
            }
            break;
        case AexrtTileFlowConvAlgorithm::ImplicitGemm3x3Stride2_20x20_128x128:
            hr = ensure_conv3x3s2_silu_implicit_gemm_exact_pipeline(device, 20u, 128u, 128u);
            if (FAILED(hr)) {
                algorithm = AexrtTileFlowConvAlgorithm::ImplicitGemm3x3;
                hr = ensure_conv3x3_silu_implicit_gemm_pipeline(device);
            }
            break;
        case AexrtTileFlowConvAlgorithm::ImplicitGemm3x3Stride2_20x20_256x256:
            hr = ensure_conv3x3s2_silu_implicit_gemm_exact_pipeline(device, 20u, 256u, 256u);
            if (FAILED(hr)) {
                algorithm = AexrtTileFlowConvAlgorithm::ImplicitGemm3x3;
                hr = ensure_conv3x3_silu_implicit_gemm_pipeline(device);
            }
            break;
        case AexrtTileFlowConvAlgorithm::ImplicitGemm3x3Stride2_10x10_256x256:
            hr = ensure_conv3x3s2_silu_implicit_gemm_exact_pipeline(device, 10u, 256u, 256u);
            if (FAILED(hr)) {
                algorithm = AexrtTileFlowConvAlgorithm::ImplicitGemm3x3;
                hr = ensure_conv3x3_silu_implicit_gemm_pipeline(device);
            }
            break;
        case AexrtTileFlowConvAlgorithm::ImplicitGemm3x3Stride2_10x10_256x512:
            hr = ensure_conv3x3s2_silu_implicit_gemm_exact_pipeline(device, 10u, 256u, 512u);
            if (FAILED(hr)) {
                algorithm = AexrtTileFlowConvAlgorithm::ImplicitGemm3x3;
                hr = ensure_conv3x3_silu_implicit_gemm_pipeline(device);
            }
            break;
        case AexrtTileFlowConvAlgorithm::ImplicitGemm3x3_40x40:
            hr = ensure_conv3x3_silu_implicit_gemm_shape_pipeline(device, 40u);
            if (FAILED(hr)) {
                algorithm = AexrtTileFlowConvAlgorithm::Spatial3x3Pack4;
                hr = ensure_conv3x3_silu_pack4_pipeline(device);
            }
            break;
        case AexrtTileFlowConvAlgorithm::ImplicitGemm3x3_20x20:
        case AexrtTileFlowConvAlgorithm::ImplicitGemm3x3_10x10: {
            const uint32_t out_dim = algorithm == AexrtTileFlowConvAlgorithm::ImplicitGemm3x3_10x10 ? 10u : 20u;
            hr = ensure_conv3x3_silu_implicit_gemm_shape_pipeline(device, out_dim);
            if (FAILED(hr)) {
                algorithm = AexrtTileFlowConvAlgorithm::ImplicitGemm3x3;
                hr = ensure_conv3x3_silu_implicit_gemm_pipeline(device);
                if (FAILED(hr) && !aexrt_env_flag("AEXRT_NATIVE_D3D12_FORCE_IMPLICIT_GEMM_3X3")) {
                    algorithm = AexrtTileFlowConvAlgorithm::Spatial3x3Pack4;
                    hr = ensure_conv3x3_silu_pack4_pipeline(device);
                }
            }
            break;
        }
        case AexrtTileFlowConvAlgorithm::Spatial3x3Pack4:
            hr = ensure_conv3x3_silu_pack4_pipeline(device);
            break;
        case AexrtTileFlowConvAlgorithm::Spatial3x3:
            hr = ensure_conv3x3_silu_pipeline(device);
            break;
