static HRESULT record_replay_stride2_conv1x1_silu_superblock(
    AexrtDevice* device,
    AexrtYoloModel* model,
    ID3D12GraphicsCommandList* list,
    size_t first_command_index,
    size_t second_command_index,
    AexrtDescriptorArena* arena,
    const std::vector<uint32_t>* consumer_counts,
    const std::vector<uint8_t>* base_skip_commands,
    bool pattern_validated = false) {
    if (!device || !model || !list || !arena) return E_INVALIDARG;
    uint32_t matched_second = 0;
    if (!pattern_validated &&
        (!match_stride2_conv1x1_silu_superblock_pattern(
             model, first_command_index, consumer_counts, nullptr, &matched_second) ||
         matched_second != second_command_index)) {
        return E_INVALIDARG;
    }
    const auto& first = model->replay_commands[first_command_index];
    const auto& second = model->replay_commands[second_command_index];
    AexrtConv2DDesc first_desc{};
    AexrtConv2DDesc second_desc{};
    if (!replay_conv_desc_from_command(first, &first_desc) ||
        !replay_conv_desc_from_command(second, &second_desc)) {
        return E_INVALIDARG;
    }

    auto& input_value = model->replay_values[first.inputs[0]];
    auto& weight0_value = model->replay_values[first.inputs[1]];
    auto& bias0_value = model->replay_values[first.inputs[2]];
    auto& weight1_value = model->replay_values[second.inputs[1]];
    auto& bias1_value = model->replay_values[second.inputs[2]];
    auto& output_value = model->replay_values[second.output];
    if (!input_value.gpu || !weight0_value.gpu || !bias0_value.gpu ||
        !weight1_value.gpu || !bias1_value.gpu ||
        !ensure_replay_gpu_storage(device, output_value)) {
        return E_INVALIDARG;
    }
    AexrtBuffer* packed_weight0 = ensure_stride2_direct_pack4_packed_weight(device, weight0_value, first_desc);
    if (!packed_weight0) return E_FAIL;
    ID3D12PipelineState* pso = nullptr;
    HRESULT hr = ensure_stride2_conv1x1_silu_pipeline(device, first_desc, second_desc, &pso);
    if (FAILED(hr) || !pso) return FAILED(hr) ? hr : E_FAIL;
    if (replay_conv_algorithm(device, first, first_desc, true) ==
            AexrtTileFlowConvAlgorithm::Spatial3x3Stride2NativeFp16PackedWeight &&
        model->tileflow_native_fp16_count != 0) {
        model->tileflow_native_fp16_count -= 1;
    }

    D3D12_CPU_DESCRIPTOR_HANDLE cursor{};
    D3D12_GPU_DESCRIPTOR_HANDLE srv_gpu{};
    if (!arena_alloc(arena, 6, &cursor, &srv_gpu)) return E_OUTOFMEMORY;
    const UINT descriptor_size = arena->descriptor_size;
    create_typed_float_srv(
        device, input_value.gpu,
        uint64_t(first_desc.batch) * first_desc.in_channels * first_desc.in_h * first_desc.in_w,
        cursor);
    cursor.ptr += descriptor_size;
    const uint64_t packed_weight_vectors = uint64_t(first_desc.out_channels / 4u) * first_desc.in_channels * 9u;
    create_float4_srv(device, packed_weight0, packed_weight_vectors, cursor);
    cursor.ptr += descriptor_size;
    create_float_srv(device, bias0_value.gpu, first_desc.out_channels, cursor);
    cursor.ptr += descriptor_size;
    create_float_srv(device, weight1_value.gpu, uint64_t(second_desc.out_channels) * second_desc.in_channels, cursor);
    cursor.ptr += descriptor_size;
    create_float_srv(device, bias1_value.gpu, second_desc.out_channels, cursor);
    cursor.ptr += descriptor_size;
    const uint64_t output_elements = uint64_t(second_desc.batch) * second_desc.out_channels * second_desc.out_h * second_desc.out_w;
    create_typed_float_uav(device, output_value.gpu, output_elements, cursor);

    transition_replay_buffer(model, list, input_value.gpu, D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
    transition_replay_buffer(model, list, packed_weight0, D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
    transition_replay_buffer(model, list, bias0_value.gpu, D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
    transition_replay_buffer(model, list, weight1_value.gpu, D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
    transition_replay_buffer(model, list, bias1_value.gpu, D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
    transition_replay_buffer(model, list, output_value.gpu, D3D12_RESOURCE_STATE_UNORDERED_ACCESS);

    D3D12_GPU_DESCRIPTOR_HANDLE uav_gpu = srv_gpu;
    uav_gpu.ptr += descriptor_size * 5u;
    list->SetComputeRootSignature(device->stride2_conv1x1_root_signature.Get());
    list->SetPipelineState(pso);
    list->SetComputeRootDescriptorTable(0, srv_gpu);
    list->SetComputeRootDescriptorTable(1, uav_gpu);
    list->SetComputeRoot32BitConstants(2, 16, first.params.data(), 0);
    const uint32_t position_tile = stride2_conv1x1_position_tile(first_desc, second_desc);
    const uint32_t spatial = first_desc.out_h * first_desc.out_w;
    list->Dispatch((spatial + position_tile - 1u) / position_tile, first_desc.batch, 1);
    return S_OK;
}

